local config = {
  str_homestory_N26dianying_90060101_1_dialog_content = "Bem, estamos aqui. O que quer que você esteja procurando deve estar nesta sala de aula. sim?",
  str_homestory_N26dianying_90060101_2_dialog_content = "Ahhh que grande ajuda.",
