  str_homestory_N26dianying_90060101_4_dialog_content = "O que há com a bajulação? Não me entenda mal, não é que eu realmente queira estar aqui, é porque eu ouvi você dizer que todos podem estar em perigo...",
  str_homestory_N26dianying_90060101_5_dialog_content = "Todos? Parece ótimo, meu pomposo jovem amigo, mas tenho um pressentimento que não é muito preciso.",
  str_homestory_N26dianying_90060101_6_dialog_content = "Suspeito que esteja mais preocupado com aquela garota.",
  str_homestory_N26dianying_90060101_7_dialog_content = "...",
  str_homestory_N26dianying_90060101_8_dialog_content = "O presidente do conselho estudantil, hmm?",
  str_homestory_N26dianying_90060101_9_dialog_content = "C-Como você sabia?!",
  str_homestory_N26dianying_90060101_10_dialog_content = "Não subestime a inteligência do departamento de segurança.",
  str_homestory_N26dianying_90060101_11_dialog_content = "Se eu estiver certo, há uma carta de amor não enviada em seu bolso.",
  str_homestory_N26dianying_90060101_12_dialog_content = "!!!",
  str_homestory_N26dianying_90060101_13_dialog_content = "Agora, apenas não nos subestime.",
  str_homestory_N26dianying_90060101_14_dialog_content = "Tudo bem, jovem, aja naturalmente agora, ou você vai deixar o gato fora do saco.",
