  str_homestory_N26dianying_90060101_20_dialog_content = "Vamos.",
  str_homestory_N26dianying_90060101_21_dialog_content = "Ei, o que você está fazendo aqui, Kaseem?",
  str_homestory_N26dianying_90060101_22_dialog_content = "S-presidente do conselho estudantil...?",
  str_homestory_N26dianying_90060101_23_dialog_content = "<size=30>Oh? Eu realmente não esperava que ela estivesse aqui. Bem, isso é suspeito...</size>",
  str_homestory_N26dianying_90060101_24_dialog_content = "<size=45>Presidente! Como você está aqui?</size>",
  str_homestory_N26dianying_90060101_25_dialog_content = "Não deve ser uma surpresa! Estou verificando o equipamento para o festival do campus.",
  str_homestory_N26dianying_90060101_26_dialog_content = "O vice-presidente e um aluno prestativo também estão ajudando com os cheques.",
  str_homestory_N26dianying_90060101_27_dialog_content = "<size=30>Eu acho que há uma grande possibilidade de que artigos perigosos tenham sido escondidos entre o equipamento.</size>",
  str_homestory_N26dianying_90060101_28_dialog_content = "<size=30>Então, o que você está pensando?</size>",
  str_homestory_N26dianying_90060101_29_dialog_content = "Hmm... não reconheço sua amiga aqui, ela é da nossa escola?",
  str_homestory_N26dianying_90060101_30_dialog_content = "Seu amigo aqui... não parece fazer parte da nossa escola.",
  str_homestory_N26dianying_90060101_31_dialog_content = "Vice-presidente...",
  str_homestory_N26dianying_90060101_32_dialog_content = "<size=30>Uh oh... Ela é aquela vice-presidente excessivamente cautelosa?</size>",
  str_homestory_N26dianying_90060101_33_dialog_content = "<size=30>Isso pode não ser tão fácil, apesar da aparência cordial.</size>",
  str_homestory_N26dianying_90060101_34_dialog_content = "<size=30>Ajude-me a pensar em algo, rápido.</size>",
  str_homestory_N26dianying_90060101_35_dialog_content = "Vou tentar.",
  str_homestory_N26dianying_90060101_36_dialog_content = "Ela... Ela é...",
  str_homestory_N26dianying_90060101_37_option_content = "Amiga",
