  str_homestory_N26dianying_90060101_39_dialog_content = "S-Ela é minha namorada!",
  str_homestory_N26dianying_90060101_40_dialog_content = "Er, você não acha que é uma escolha muito perigosa, chubb.",
  str_homestory_N26dianying_90060101_41_dialog_content = "G-Namorada?!",
  str_homestory_N26dianying_90060101_42_dialog_content = "Desde quando?!",
  str_homestory_N26dianying_90060101_43_dialog_content = "<size=30>Eu não esperava que você estivesse interessado em mim, jovem...</size>",
  str_homestory_N26dianying_90060101_44_dialog_content = "<size=30>Não esperava que você se interessasse por mim, meu jovem! Mas me desculpe, meu coração já pertence a outro.</size>",
  str_homestory_N26dianying_90060101_45_dialog_content = "<size=30>Você não acha que esse tipo de desculpa é óbvio demais?</size>",
  str_homestory_N26dianying_90060101_46_dialog_content = "<size=30>E esse tipo de desculpa não ajuda em nada a situação.</size>",
  str_homestory_N26dianying_90060101_47_dialog_content = "D-Desculpe...",
  str_homestory_N26dianying_90060101_48_option_content = "Prima",
  str_homestory_N26dianying_90060101_49_dialog_content = "Basta dizer que ela é sua prima! Passo acima!",
  str_homestory_N26dianying_90060101_50_dialog_content = "Oh, este é meu primo, sim!",
  str_homestory_N26dianying_90060101_51_dialog_content = "Eles não se parecem em nada, dificilmente aparentados, chubb.",
  str_homestory_N26dianying_90060101_52_dialog_content = "Ah, seu primo! Você não vai nos apresentar?",
  str_homestory_N26dianying_90060101_53_dialog_content = "Oh, sua prima, é? Você não vai nos apresentar?",
  str_homestory_N26dianying_90060101_54_dialog_content = "Sou só eu ou a discrepância de idade está um pouco errada?",
  str_homestory_N26dianying_90060101_55_dialog_content = "Não posso deixar de sentir que há algo um pouco estranho na diferença de idade.",
  str_homestory_N26dianying_90060101_56_dialog_content = "Não não. Ela sempre pareceu madura para sua idade. Ela é assim desde os oito anos.",
  str_homestory_N26dianying_90060101_57_dialog_content = "É assim mesmo? Isso é realmente algo...",
  str_homestory_N26dianying_90060101_58_dialog_content = "<size=30>Você está falando besteira.</size>",
  str_homestory_N26dianying_90060101_59_dialog_content = "<size=30>Isso parece errado... Estou começando a duvidar do roteiro...</size>",
  str_homestory_N26dianying_90060101_60_dialog_content = "<size=30>Isso não fará com que todos se concentrem ainda mais em mim?</size>",
  str_homestory_N26dianying_90060101_61_dialog_content = "<size=30>Esqueça, isso só vai fazer com que todos se concentrem ainda mais em mim.</size>",
  str_homestory_N26dianying_90060101_62_dialog_content = "Sinto muito...",
  str_homestory_N26dianying_90060101_63_option_content = "Vizinho",
  str_homestory_N26dianying_90060101_64_dialog_content = "Melhor apenas dizer que ela é uma vizinha. Isso deve ser seguro!",
  str_homestory_N26dianying_90060101_65_dialog_content = "S-Ela é minha vizinha.",
  str_homestory_N26dianying_90060101_66_dialog_content = "Não posso deixar de sentir que está cavando sua própria cova, chub.",
  str_homestory_N26dianying_90060101_67_dialog_content = "Vizinho?",
  str_homestory_N26dianying_90060101_68_dialog_content = "O presidente do conselho estudantil não mora perto de você?",
  str_homestory_N26dianying_90060101_69_dialog_content = "Presidente Theresa, você a reconhece?",
  str_homestory_N26dianying_90060101_70_dialog_content = "Não... Não, eu não...",
  str_homestory_N26dianying_90060101_71_dialog_content = "Você acabou de se mudar para a área?",
  str_homestory_N26dianying_90060101_72_dialog_content = "Oh, haha... Eu, eu cometi um erro.",
  str_homestory_N26dianying_90060101_73_dialog_content = "<size=30>Você é uma verdadeira causa perdida. Você não consegue pensar em nada melhor?</size>",
  str_homestory_N26dianying_90060101_74_dialog_content = "<size=30>Eu sinto Muito! Deixe-me pensar...</size>",
  str_homestory_N26dianying_90060101_75_dialog_content = "... Entendi! Acabei de esbarrar com ela no caminho para cá. Ela é uma das alunas da nossa escola.",
  str_homestory_N26dianying_90060101_76_dialog_content = "Ela tinha ouvido falar do nosso festival no campus, o que a lembrou de seu tempo aqui, então ela queria ir junto.",
  str_homestory_N26dianying_90060101_77_dialog_content = "Então é assim, ex-aluno, né?",
  str_homestory_N26dianying_90060101_78_dialog_content = "Isso explica por que ela parece mais velha.",
  str_homestory_N26dianying_90060101_79_dialog_content = "(Bom trabalho, garoto. Parece que nós acabamos com isso por enquanto.)",
  str_homestory_N26dianying_90060101_80_dialog_content = "Todo o equipamento foi verificado, Presidente.",
  str_homestory_N26dianying_90060101_81_dialog_content = "Eu agradeço.",
  str_homestory_N26dianying_90060101_82_dialog_content = "D? Um menino? Ela vai cruzar escalando o papel?",
  str_homestory_N26dianying_90060101_83_dialog_content = "Betel está improvisando.",
  str_homestory_N26dianying_90060101_84_dialog_content = "Bem, então, por favor, sinta-se à vontade para dar uma olhada e deixe-nos saber se você tem alguma sugestão.",
  str_homestory_N26dianying_90060101_85_dialog_content = "Excelente! Vou dar uma boa olhada e oferecer algumas ideias da perspectiva de minha pós-graduação.",
  str_homestory_N26dianying_90060101_86_dialog_content = "O que é isso, senhorita presidente?!",
  str_homestory_N26dianying_90060101_87_dialog_content = "Esta é... uma nova fritadeira comum?",
  str_homestory_N26dianying_90060101_88_dialog_content = "Huh? Esse é o eletrodoméstico que frita alimentos sem precisar de óleo, certo?",
  str_homestory_N26dianying_90060101_89_dialog_content = "Isso mesmo. Ambos são saudáveis e muito populares agora.",
  str_homestory_N26dianying_90060101_90_dialog_content = "<size=30>Entendo... Parece que é fácil esconder alguma coisa nessas cestas de frituras.</size>",
  str_homestory_N26dianying_90060101_91_dialog_content = "<size=30>Dispositivos de interesse também poderiam hipoteticamente ser acionados por aquecimento.</size>",
  str_homestory_N26dianying_90060101_92_dialog_content = "<size=30>Dispositivos de interesse também poderiam hipoteticamente ser acionados por aquecimento. Melhor olhar para dentro.</size>",
  str_homestory_N26dianying_90060101_93_dialog_content = "Não parece ótimo para cozinhar, para ser honesto.",
  str_homestory_N26dianying_90060101_94_dialog_content = "Oh, este é apenas um acessório fornecido pelo nosso clube de cosplay.",
  str_homestory_N26dianying_90060101_95_dialog_content = "A... fábrica de alquimia não fez isso?",
  str_homestory_N26dianying_90060101_96_dialog_content = "A fábrica de alquimia de Theresa?",
  str_homestory_N26dianying_90060101_97_dialog_content = "Muito engraçado.",
  str_homestory_N26dianying_90060101_98_dialog_content = "...",
  str_homestory_N26dianying_90060101_99_dialog_content = "(Você diz para verificar dentro? Acha que posso?)",
  str_homestory_N26dianying_90060101_100_dialog_content = "Esse é o meu prato especial!",
  str_homestory_N26dianying_90060101_101_dialog_content = "Uma grande amiga me passou a receita. É borscht de beterraba.",
  str_homestory_N26dianying_90060101_102_dialog_content = "É refrescante e nutritivo para a alma.",
  str_homestory_N26dianying_90060101_103_dialog_content = "Borscht de beterraba... Você quer dizer...",
  str_homestory_N26dianying_90060101_104_dialog_content = "Oh, você deve ter comido o borscht do meu amigo antes, Kaseem.",
  str_homestory_N26dianying_90060101_105_dialog_content = "Eu... eu não sei.",
  str_homestory_N26dianying_90060101_106_dialog_content = "Esta não é uma boa conversa, seja como for, então vamos mudar de assunto.",
  str_homestory_N26dianying_90060101_107_dialog_content = "...",
  str_homestory_N26dianying_90060101_108_dialog_content = "(Você quer verificar a sopa...? Sério? Na verdade, é bem perigoso.)",
  str_homestory_N26dianying_90060101_108X1_dialog_content = "Hmm... Parece um pouco vago aqui.",
  str_homestory_N26dianying_90060101_108X2_dialog_content = "Talvez eles ainda estejam preparando as coisas?",
  str_homestory_N26dianying_90060101_108X3_dialog_content = "É possível, mas sinto cheiro de perigo por perto.",
  str_homestory_N26dianying_90060101_109_dialog_content = "Hã? O que você disse?",
  str_homestory_N26dianying_90060101_110_dialog_content = "Nenhuma coisa. Continue fazendo suas coisas, vou dar uma olhada.",
  str_homestory_N26dianying_90060101_111_dialog_content = "Ah... Tá bom.",
  str_homestory_N26dianying_90060101_112_dialog_content = "A propósito, Kaseem, como estão os outros preparativos para o festival?",
  str_homestory_N26dianying_90060101_113_dialog_content = "Ah, bem, o campo de esportes...",
  str_homestory_N26dianying_90060101_114_dialog_content = "Ei! Você está sendo muito óbvio. Todo mundo pode ver você se esgueirando assim!",
  str_homestory_N26dianying_90060101_115_dialog_content = "...",
  str_homestory_N26dianying_90060101_116_dialog_content = "(O quê? Você quer que eu encontre uma maneira de ganhar mais tempo? O que, como ter algum tipo de detector escondido na máscara para farejar artigos perigosos?)",
  str_homestory_N26dianying_90060101_117_dialog_content = "(O quê? Você quer que eu encontre uma maneira de ganhar mais tempo? O que, como ter algum tipo de detector escondido no bolso para procurar artigos perigosos?)",
  str_homestory_N26dianying_90060101_118_dialog_content = "(Como você pode transmitir tanto apenas com seus olhos?)",
  str_homestory_N26dianying_90060101_119_dialog_content = "(Na verdade, como posso saber o que você quer dizer com tanta clareza?!)",
  str_homestory_N26dianying_90060101_120_dialog_content = "Droga... Preciso cobri-la de alguma forma...",
  str_homestory_N26dianying_90060101_121_dialog_content = "Qual é o problema, Kaseem? Há algo de errado com seus olhos?",
  str_homestory_N26dianying_90060101_122_dialog_content = "Oh, senhorita presidente, eu...",
  str_homestory_N26dianying_90060101_123_option_content = "Vamos cantar!",
  str_homestory_N26dianying_90060101_123_dialog_content = "Não há tempo! Use sua voz para atrair sua atenção!",
  str_homestory_N26dianying_90060101_124_dialog_content = "Eu quero cantar para você a música para o festival do campus!",
  str_homestory_N26dianying_90060101_125_dialog_content = "Hã?",
  str_homestory_N26dianying_90060101_126_dialog_content = "Eu tenho praticado secretamente esta música do rádio. E eu me esforcei muito, então preste atenção!",
  str_homestory_N26dianying_90060101_127_dialog_content = "Na verdade, sou um cantor incrível, apenas observe-me atingir todas as notas altas!",
  str_homestory_N26dianying_90060101_128_dialog_content = "Ohh? Você vai cantar? Então eu vou fazer a harmonia!",
  str_homestory_N26dianying_90060101_129_dialog_content = "Ohh? Você vai cantar? Deixe-me acompanhá-lo com esses sinos.",
  str_homestory_N26dianying_90060101_130_dialog_content = "Súbita explosão de música como um idiota.",
  str_homestory_N26dianying_90060101_131_dialog_content = "Que idiota... De repente começou a cantar.",
  str_homestory_N26dianying_90060101_132_dialog_content = "Ainda temos muito que preparar!",
  str_homestory_N26dianying_90060101_133_dialog_content = "Ainda temos muito o que preparar.",
  str_homestory_N26dianying_90060101_134_option_content = "Por favor, devolva a fita de vídeo!",
  str_homestory_N26dianying_90060101_134_dialog_content = "Você se lembrou do vídeo de repente!",
  str_homestory_N26dianying_90060101_135_dialog_content = "Presidente!",
  str_homestory_N26dianying_90060101_136_dialog_content = "Hum?",
  str_homestory_N26dianying_90060101_137_dialog_content = "Você pode devolver o vídeo que te emprestei?!",
  str_homestory_N26dianying_90060101_138_dialog_content = "Huh? Você só me emprestou ontem!",
  str_homestory_N26dianying_90060101_139_dialog_content = "E você concordou em me emprestar \"Cloud Island Ultra Warrior: The General\" por uma semana...",
  str_homestory_N26dianying_90060101_140_dialog_content = "E agora de repente você precisa dele de volta?",
  str_homestory_N26dianying_90060101_141_dialog_content = "Na verdade... esqueci que tinha outro vídeo no caso... Coisa que não é para meninas verem!",
  str_homestory_N26dianying_90060101_142_dialog_content = "O conteúdo de \"Railway Warrior Bros\" é muito sangrento!",
  str_homestory_N26dianying_90060101_143_dialog_content = "Ah, e-entendi...",
  str_homestory_N26dianying_90060101_144_dialog_content = "Ouça, vou trazer o certo um pouco mais tarde.",
  str_homestory_N26dianying_90060101_145_option_content = "Waffle!",
  str_homestory_N26dianying_90060101_145_dialog_content = "Uau lá! Este filme é para pessoas de todas as idades. Olha a escala!",
  str_homestory_N26dianying_90060101_146_dialog_content = "Presidente Teresa!",
  str_homestory_N26dianying_90060101_147_dialog_content = "Hum?",
  str_homestory_N26dianying_90060101_148_dialog_content = "Qual é o seu tipo...?",
  str_homestory_N26dianying_90060101_149_dialog_content = "P-Por que você me perguntou isso de repente??",
  str_homestory_N26dianying_90060101_150_dialog_content = "I-Se você insiste... Você...",
  str_homestory_N26dianying_90060101_151_dialog_content = "Seu idiota! Por que eu falaria sobre esse tipo de coisa na frente de tantas pessoas?!",
  str_homestory_N26dianying_90060101_152_dialog_content = "Ahem... Isso está um pouco fora de ordem, Kaseem.",
  str_homestory_N26dianying_90060101_153_dialog_content = "Uh... Precisa que eu o desculpe?",
  str_homestory_N26dianying_90060101_154_dialog_content = "É isso que o livro chama de line drive?",
  str_homestory_N26dianying_90060101_155_dialog_content = "Não precisa!",
  str_homestory_N26dianying_90060101_155X1_dialog_content = "Do que você está falando, Kaseem!?",
  str_homestory_N26dianying_90060101_156_dialog_content = "Bem, realmente! O que você acha, sênior, sou só eu, ou Kaseem está agindo muito estranho hoje?",
  str_homestory_N26dianying_90060101_157_dialog_content = "Huh? Senior? O que você está procurando por aí?",
  str_homestory_N26dianying_90060101_158_dialog_content = "Oops, parece que fui pego de surpresa.",
  str_homestory_N26dianying_90060101_159_dialog_content = "Nada a fazer senão recomeçar minha investigação... Com essa caneta piscante que apaga memórias!",
  str_homestory_N26dianying_90060101_160_dialog_content = "Nada mais resta senão recomeçar, com esta chave que apaga memórias...!",
  str_homestory_N26dianying_90060101_161_dialog_content = "Isto é uma máquina de venda automática, Srta. Presidente?",
  str_homestory_N26dianying_90060101_162_dialog_content = "Sim.",
  str_homestory_N26dianying_90060101_163_dialog_content = "Eu pensei que as pessoas poderiam querer uma bebida para acompanhar seus lanches.",
  str_homestory_N26dianying_90060101_164_dialog_content = "Então eu encontrei uma maneira de pegar um emprestado especialmente.",
  str_homestory_N26dianying_90060101_165_dialog_content = "Uau, isso é bem impressionante. Não é à toa que você é o presidente.",
  str_homestory_N26dianying_90060101_166_dialog_content = "Fui eu quem o trouxe até aqui!",
  str_homestory_N26dianying_90060101_167_dialog_content = "...",
  str_homestory_N26dianying_90060101_168_dialog_content = "(Sinais oculares novamente... Hein? Essa área foi verificada? Nenhum artigo perigoso?)",
  str_homestory_N26dianying_90060101_169_dialog_content = "(Continue enrolando... Aquela máquina de venda automática é super suspeita, está abastecida com montes de bebidas que eu nunca vi antes!)",
  str_homestory_N26dianying_90060101_170_dialog_content = "(Leite com sabor de menta de peixe? Rust pop? Suco de vegetais?)",
  str_homestory_N26dianying_90060101_171_dialog_content = "(Agora é realmente a hora de pensar sobre isso?! Estou meio que no fim das minhas forças aqui!)",
  str_homestory_N26dianying_90060101_172_dialog_content = "(E de que vegetal exatamente é feito o suco? Não é como um chá esquisito, é?)",
  str_homestory_N26dianying_90060101_173_dialog_content = "Só tenho que continuar...",
  str_homestory_N26dianying_90060101_174_dialog_content = "Isso é uma bateria, senhorita presidente?",
  str_homestory_N26dianying_90060101_175_dialog_content = "Sim, com certeza é.",
  str_homestory_N26dianying_90060101_176_dialog_content = "Alguns departamentos vão fazer um show para o festival, então eles deixaram isso aqui por enquanto.",
  str_homestory_N26dianying_90060101_177_dialog_content = "Entendi.",
  str_homestory_N26dianying_90060101_178_dialog_content = "...",
  str_homestory_N26dianying_90060101_179_dialog_content = "(O tipo de coisa que estamos procurando pode estar escondido dentro dos tambores. Devemos rasgá-los?)",
  str_homestory_N26dianying_90060101_180_dialog_content = "(Espere um pouco. Se estiverem rasgados, serão inúteis!)",
  str_homestory_N26dianying_90060101_182_dialog_content = "Um peru, senhorita presidente?",
  str_homestory_N26dianying_90060101_183_dialog_content = "Por que o festival precisa de peru?",
  str_homestory_N26dianying_90060101_184_dialog_content = "Ah, esse é o gato de um aluno... Mas não faço ideia de onde ele tirou o peru...",
  str_homestory_N26dianying_90060101_185_dialog_content = "Oh, certo. Sabe, uma vez tive um gato que me ajudava no trabalho.",
  str_homestory_N26dianying_90060101_186_dialog_content = "...",
  str_homestory_N26dianying_90060101_187_dialog_content = "(O quê? Algo pode estar escondido dentro do peru? Quer investigar sem estragar?)",
  str_homestory_N26dianying_90060101_188_dialog_content = "(Isso é ... mesmo possível? Se você conseguir, terá que me ensinar como.)",
  str_homestory_N26dianying_90060101_188X1_dialog_content = "Está vazio...",
  str_homestory_N26dianying_90060101_188X2_dialog_content = "Isso é realmente para se preparar para um festival no campus?",
  str_homestory_N26dianying_90060101_188X3_dialog_content = "É realmente incomum. Havia algo aqui antes.",
  str_homestory_N26dianying_90060101_188X4_dialog_content = "Isso é muito suspeito. Preciso investigar com cuidado!",
  str_homestory_N26dianying_90060101_188X5_dialog_content = "Me proteja!",
  str_homestory_N26dianying_90060101_188X6_dialog_content = "Huh? Mas não há cobertura aqui!",
  str_homestory_N26dianying_90060101_190_option_content = "Dança!",
  str_homestory_N26dianying_90060101_190_dialog_content = "Rapidamente, use o movimento que você pratica há muito tempo!",
  str_homestory_N26dianying_90060101_191_dialog_content = "Esqueça!",
  str_homestory_N26dianying_90060101_192_dialog_content = "Todos, por favor, assistam—!",
  str_homestory_N26dianying_90060101_193_dialog_content = "Minha dança incrível e maravilhosa!",
  str_homestory_N26dianying_90060101_193X1_dialog_content = "Este movimento é a lendária dança planet walk? Chubb!",
  str_homestory_N26dianying_90060101_194_dialog_content = "Aaaa...!!",
  str_homestory_N26dianying_90060101_195_dialog_content = "Kaseem, hoje você está realmente...",
  str_homestory_N26dianying_90060101_196_dialog_content = "Excitável!",
  str_homestory_N26dianying_90060101_197_dialog_content = "Oh? Obrigado!",
  str_homestory_N26dianying_90060101_198_dialog_content = "(Será que ela realmente gosta de mim assim?)",
  str_homestory_N26dianying_90060101_199_dialog_content = "Que burro...",
  str_homestory_N26dianying_90060101_200_dialog_content = "Você, tipo, perdeu a cabeça...",
  str_homestory_N26dianying_90060101_201_dialog_content = "Há algo muito estranho acontecendo com você hoje.",
  str_homestory_N26dianying_90060101_202_dialog_content = "Incrível! Você pode me ensinar a dançar, por favor!",
  str_homestory_N26dianying_90060101_203_option_content = "Palma lida?",
  str_homestory_N26dianying_90060101_203_dialog_content = "Rapidamente, use o conhecimento que você aprendeu nos livros...!",
  str_homestory_N26dianying_90060101_203X1_dialog_content = "Sim! Lembre-se dos pontos mencionados no livro \"Aproximando-se rapidamente de seus inimigos\" agora...",
  str_homestory_N26dianying_90060101_203X2_dialog_content = "É óbvio pelo título do livro que há muitos problemas com ele, chubb!",
  str_homestory_N26dianying_90060101_204_dialog_content = "Permita-me ler sua sorte em suas mãos!",
  str_homestory_N26dianying_90060101_205_dialog_content = "Me desculpe... Não posso aceitar isso, mesmo como um preenchimento de conversa.",
  str_homestory_N26dianying_90060101_206_dialog_content = "Você é um idiota? Melhor deixar-me ler a palma da mão!",
  str_homestory_N26dianying_90060101_207_dialog_content = "Enquanto estamos nisso, deixe-me garantir que sua linha de vida termine hoje.",
  str_homestory_N26dianying_90060101_208_dialog_content = "Claro, e só vou confirmar que sua linha de vida realmente termina hoje.",
  str_homestory_N26dianying_90060101_209_dialog_content = "Bem, realmente! O que você acha, sênior, sou só eu, ou Kaseem está agindo muito estranho hoje?",
  str_homestory_N26dianying_90060101_210_dialog_content = "Huh? Senior? O que você está procurando por aí?",
  str_homestory_N26dianying_90060101_211_dialog_content = "Oops, parece que fui pego de surpresa.",
  str_homestory_N26dianying_90060101_212_dialog_content = "Nada mais a fazer senão recomeçar, com esta caneta que apaga memórias...!",
  str_homestory_N26dianying_90060101_213_dialog_content = "Nada mais resta senão recomeçar, com esta chave que apaga memórias...!",
  str_homestory_N26dianying_90060101_214_option_content = "OVNI?",
  str_homestory_N26dianying_90060101_214_dialog_content = "Métodos extremamente tradicionais costumam ser os mais eficazes!",
  str_homestory_N26dianying_90060101_215_dialog_content = "Lá! UM OVNI!",
  str_homestory_N26dianying_90060101_216_dialog_content = "Uma olhadela!",
  str_homestory_N26dianying_90060101_217_dialog_content = "OVNI! Lá!",
  str_homestory_N26dianying_90060101_218_dialog_content = "...",
  str_homestory_N26dianying_90060101_219_dialog_content = "...",
  str_homestory_N26dianying_90060101_220_dialog_content = "...",
  str_homestory_N26dianying_90060101_220X1_dialog_content = "...",
  str_homestory_N26dianying_90060101_221_dialog_content = "Bem, realmente. Quer olhar para ele, sênior? Kaseem está agindo de forma muito estranha hoje.",
  str_homestory_N26dianying_90060101_222_dialog_content = "Huh? Senior? O que você está procurando por aí?",
  str_homestory_N26dianying_90060101_223_dialog_content = "Oops, parece que fui pego de surpresa.",
  str_homestory_N26dianying_90060101_224_dialog_content = "Nada mais a fazer senão recomeçar, com esta caneta que apaga memórias...!",
  str_homestory_N26dianying_90060101_225_dialog_content = "Nada mais resta senão recomeçar, com esta chave que apaga memórias...!",
  str_homestory_N26dianying_90060101_226_dialog_content = "...",
  str_homestory_N26dianying_90060101_227_dialog_content = "(Terminou de verificar aqui e ainda nada?)",
  str_homestory_N26dianying_90060101_228_dialog_content = "O que é isso, senhorita presidente?",
  str_homestory_N26dianying_90060101_229_dialog_content = "Oh! Eu esqueci de dizer.",
  str_homestory_N26dianying_90060101_230_dialog_content = "Este é o ponto alto do festival!",
  str_homestory_N26dianying_90060101_231_dialog_content = "Basta puxar aqui e a máquina põe um ovo.",
  str_homestory_N26dianying_90060101_232_dialog_content = "Existem muitos pratos diferentes e saborosos dentro de cada ovo. É uma engenhoca maravilhosa!",
  str_homestory_N26dianying_90060101_233_dialog_content = "Quando foi que conseguimos uma máquina tão incrível...?",
  str_homestory_N26dianying_90060101_234_dialog_content = "Nosso aluno muito gentil doou. Aparentemente, é muito caro.",
  str_homestory_N26dianying_90060101_235_dialog_content = "Coisas boas devem ser compartilhadas com todos, heheh.",
  str_homestory_N26dianying_90060101_236_dialog_content = "As coisas favoritas de todos estão dentro, heheh.",
  str_homestory_N26dianying_90060101_237_dialog_content = "Talvez devêssemos aproveitar a oportunidade para testá-lo novamente e dar a Kaseem e nosso sênior a chance de ver o quão incrível é.",
  str_homestory_N26dianying_90060101_238_dialog_content = "<size=30>Esta engenhoca é suspeita e o último lugar onde algo perigoso pode estar escondido. Devemos aproveitar esta chance.</size>",
  str_homestory_N26dianying_90060101_239_dialog_content = "<size=30>Entendi. Não se preocupe.</size>",
  str_homestory_N26dianying_90060101_240_dialog_content = "Então, por favor...",
  str_homestory_N26dianying_90060101_243_dialog_content = "<size=30>Como é possível... Recebemos más informações?</size>",
  str_homestory_N26dianying_90060101_244_dialog_content = "<size=30>Então, o que fazemos?</size>",
  str_homestory_N26dianying_90060101_245_dialog_content = "<size=30>Vamos sair daqui por enquanto. Eu posso ser perturbado se ficarmos muito mais tempo.</size>",
  str_homestory_N26dianying_90060101_246_dialog_content = "Ah, ainda tenho coisas para fazer. Receio que preciso ir.",
  str_homestory_N26dianying_90060101_247_dialog_content = "Desejo-lhe tudo de bom para o festival do campus.",
  str_homestory_N26dianying_90060101_248_dialog_content = "Ah ok. Obrigado, sênior.",
  str_homestory_N26dianying_90060101_249_dialog_content = "Indo embora, assim? Há algo suspeito sobre este sênior.",
  str_homestory_N26dianying_90060101_250_dialog_content = "...",
  str_homestory_N26dianying_90060101_251_option_content = "O presidente o opera",
  str_homestory_N26dianying_90060101_252_dialog_content = "Deixe a protagonista fazer isso!",
  str_homestory_N26dianying_90060101_253_dialog_content = "O presidente gostaria de operá-lo?",
  str_homestory_N26dianying_90060101_254_dialog_content = "Quer mesmo que o presidente faça isso? Você não esqueceu algo importante, chubb?",
  str_homestory_N26dianying_90060101_255_dialog_content = "Tudo bem então, vou fazer papel de bobo.",
  str_homestory_N26dianying_90060101_256_dialog_content = "Hrrrnnnng-!",
  str_homestory_N26dianying_90060101_257_dialog_content = "Ha! Eu realmente não pensei que haveria um ovo.",
  str_homestory_N26dianying_90060101_258_dialog_content = "Parece um ovo normal...",
  str_homestory_N26dianying_90060101_259_dialog_content = "Tem tiramisu dentro.",
  str_homestory_N26dianying_90060101_260_dialog_content = "A inteligência poderia estar errada? Nada a fazer senão continuar procurando.",
  str_homestory_N26dianying_90060101_261_option_content = "opere você mesmo",
  str_homestory_N26dianying_90060101_262_dialog_content = "Me deixe fazê-lo. Pelo menos você ficará tranquilo.",
  str_homestory_N26dianying_90060101_263_dialog_content = "Eu vou fazer isso!",
  str_homestory_N26dianying_90060101_264_dialog_content = "Só puxar aqui, certo?",
  str_homestory_N26dianying_90060101_265_dialog_content = "Sim.",
  str_homestory_N26dianying_90060101_266_dialog_content = "Pronto!",
  str_homestory_N26dianying_90060101_267_dialog_content = "Está piscando e parece haver um mil-folhas dentro?",
  str_homestory_N26dianying_90060101_268_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  str_homestory_N26dianying_90060101_269_dialog_content = "Esperar! O que é isso?!",
  str_homestory_N26dianying_90060101_270_dialog_content = "Droga, descoberto! Então terei todos vocês—!",
  str_homestory_N26dianying_90060101_271_dialog_content = "O que está acontecendo?",
  str_homestory_N26dianying_90060101_272_dialog_content = "O que está acontecendo? Esperei a noite toda pelo clímax, chubb!",
  str_homestory_N26dianying_90060101_273_option_content = "Convide o sênior",
  str_homestory_N26dianying_90060101_274_dialog_content = "Hmm, ela trouxe um dispositivo para detectar objetos perigosos, então talvez seja mais seguro deixar o sênior verificar.",
  str_homestory_N26dianying_90060101_275_dialog_content = "O sênior gostaria de tentar?",
  str_homestory_N26dianying_90060101_275X1_dialog_content = "Hmm, você parece um pouco mais inteligente, chubb!",
  str_homestory_N26dianying_90060101_276_dialog_content = "Oh, escolha sábia. Claro, vou tentar.",
  str_homestory_N26dianying_90060101_277_dialog_content = "Este ovo tem uma guloseima saborosa dentro?",
  str_homestory_N26dianying_90060101_278_dialog_content = "Acho que é um bolo de floresta negra lá dentro.",
  str_homestory_N26dianying_90060101_279_dialog_content = "(Huh? Meu detector está reagindo.)",
  str_homestory_N26dianying_90060101_280_dialog_content = "Ninguém se move! Estou com o departamento de segurança!",
  str_homestory_N26dianying_90060101_281_dialog_content = "Aqui está o meu distintivo. Agora, vou trazer todos para interrogatório.",
  str_homestory_N26dianying_90060101_282_dialog_content = "Senior?",
  str_homestory_N26dianying_90060101_283_dialog_content = "Droga, descoberto! Então terei todos vocês—!",
  str_homestory_N26dianying_90060101_284_dialog_content = "Eh? O que você está fazendo, aluno entusiasta desconhecido?",
  str_homestory_N26dianying_90060101_285_dialog_content = "Huh? Que? Por que o controle não está funcionando?",
  str_homestory_N26dianying_90060101_286_dialog_content = "Huh? Que? Por que o controle não está funcionando? O departamento de adereços não cuidou bem disso?",
  str_homestory_N26dianying_90060101_287_dialog_content = "Crédulo demais, o detector em minha máscara tem um bloqueador de pequeno alcance.",
  str_homestory_N26dianying_90060101_288_dialog_content = "Crédulo demais, meu detector tem um bloqueador de pequeno alcance.",
  str_homestory_N26dianying_90060101_289_dialog_content = "Droga... Assim que for ativado, toda a escola vai virar doces, igual aquelas casinhas de doces dos contos de fadas!",
  str_homestory_N26dianying_90060101_290_dialog_content = "Eu poderia escapar me escondendo dentro de uma parede de chocolate...",
  str_homestory_N26dianying_90060101_291_dialog_content = "Se possível, gostaria de voar em um navio de chocolate.",
  str_homestory_N26dianying_90060101_292_dialog_content = "... Aí, aí a glicemia vai ficar muito alta... Não! É muito perigoso!",
  str_homestory_N26dianying_90060101_293_dialog_content = "Já faz um tempo que estou observando o Império dos Carboidratos, então é melhor vocês virem em silêncio.",
  str_homestory_N26dianying_90060101_294_dialog_content = "Eu tenho observado o seu Sugar Kingdom por um tempo agora, então é melhor que todos venham em silêncio.",
  str_homestory_N26dianying_90060101_295_dialog_content = "Você acha que vai me levar tão facilmente?",
  str_homestory_N26dianying_90060101_296_dialog_content = "Huh? Eu não posso me mover!",
  str_homestory_N26dianying_90060101_297_dialog_content = "Argh...!",
  str_homestory_N26dianying_90060101_298_dialog_content = "P-Presidente...!",
  str_homestory_N26dianying_90060101_299_dialog_content = "Vocês...! Estudante entusiasmado!",
  str_homestory_N26dianying_90060101_300_dialog_content = "Você teve sorte desta vez. Acho que vou ter que usar o ás na manga.",
  str_homestory_N26dianying_90060101_301_dialog_content = "Mas nosso nobre sonho de viciar as pessoas em açúcar não se extinguirá!",
  str_homestory_N26dianying_90060101_302_dialog_content = "Veremos!",
  str_homestory_N26dianying_90060101_303_dialog_content = "Não... eu não vou deixar você ir...",
  str_homestory_N26dianying_90060101_304_dialog_content = "Vice presidente?!",
  str_homestory_N26dianying_90060101_305_dialog_content = "Acha que pode causar tanto barulho no festival do campus e depois sair tão facilmente?",
  str_homestory_N26dianying_90060101_306_dialog_content = "O que?! Como é que você pode se mover?",
  str_homestory_N26dianying_90060101_307_dialog_content = "O que?! Como é que você pode se mover? Diretor! Isso não está certo!",
  str_homestory_N26dianying_90060101_308_dialog_content = "Quem interferiu em nosso equipamento? Seu departamento de segurança nunca seria capaz de fazer isso, então QUEM FOI?!",
  str_homestory_N26dianying_90060101_309_dialog_content = "Toma essa!",
  str_homestory_N26dianying_90060101_310_dialog_content = "Entregue todas as sobremesas!",
  str_homestory_N26dianying_90060101_311_dialog_content = "O cara que queria que todos viciassem em açúcar no festival foi levado embora.",
  str_homestory_N26dianying_90060101_312_dialog_content = "Oh... E lá estava eu, pensando que ele era realmente apenas um aluno interessado.",
  str_homestory_N26dianying_90060101_313_dialog_content = "Também recuperei todas as sobremesas.",
  str_homestory_N26dianying_90060101_314_dialog_content = "De qualquer forma, pelo menos a paz voltou ao campus.",
  str_homestory_N26dianying_90060101_315_dialog_content = "É claro! Afinal, este é o nosso campus.",
  str_homestory_N26dianying_90060101_316_dialog_content = "Não é apenas aquele sênior do departamento de segurança. Muitas pessoas também estão procurando por isso.",
  str_homestory_N26dianying_90060201_1_dialog_content = "Oh querida, eu já estou atrasada! Só espero que o contato ainda não tenha saído...",
  str_homestory_N26dianying_90060201_2_dialog_content = "Perdoe-me senhor, mas este é o Thorngate Inn?",
  str_homestory_N26dianying_90060201_3_dialog_content = "De fato é.",
  str_homestory_N26dianying_90060201_4_dialog_content = "Servimos todos os tipos de comida aqui, perfeitos para um viajante cansado.",
  str_homestory_N26dianying_90060201_5_dialog_content = "Sem falar em alguns drinks que você não encontrará em nenhum outro lugar do mundo.",
  str_homestory_N26dianying_90060201_6_dialog_content = "Por que não ficar um pouco e experimentar meus produtos?",
  str_homestory_N26dianying_90060201_7_dialog_content = "Minha pousada pode não parecer grande coisa, mas nossos pratos ganharam concursos por todo o reino.",
  str_homestory_N26dianying_90060201_8_dialog_content = "Ver? Ali está o nosso maior troféu até agora.",
  str_homestory_N26dianying_90060201_9_dialog_content = "Com certeza é um troféu interessante...",
  str_homestory_N26dianying_90060201_10_dialog_content = "Também temos vários sacos de areia espalhados pela pousada.",
  str_homestory_N26dianying_90060201_11_dialog_content = "Se quiser, pode esticar as pernas um pouco.",
  str_homestory_N26dianying_90060201_12_dialog_content = "O que esse tipo de coisa está fazendo em uma pousada...?",
  str_homestory_N26dianying_90060201_13_dialog_content = "Bem, a pousada parece bastante limpa... Sim, acho que vou ficar um pouco.",
  str_homestory_N26dianying_90060201_14_dialog_content = "Tem um lugar vazio bem ali. Sinta-se em casa, amigo.",
  str_homestory_N26dianying_90060201_15_dialog_content = "Este lugar faz muito bem por si mesmo. . .",
  str_homestory_N26dianying_90060201_16_dialog_content = "Nem é hora de comer, mas a pousada está cheia de clientes!",
  str_homestory_N26dianying_90060201_17_dialog_content = "Em todo caso, estou aqui para ver um velho conhecido, então não precisarei de minha própria mesa.",
  str_homestory_N26dianying_90060201_18_dialog_content = "Bem, o estilo parece fora de lugar aqui.",
  str_homestory_N26dianying_90060201_19_dialog_content = "O estalajadeiro comprou enquanto viajava para um país estrangeiro?",
  str_homestory_N26dianying_90060201_20_dialog_content = "Em todo caso, estou aqui para ver um velho conhecido, então não precisarei de minha própria mesa.",
  str_homestory_N26dianying_90060201_21_dialog_content = "Agora, isso está indo longe demais...",
  str_homestory_N26dianying_90060201_22_dialog_content = "Eu não acho que uma colcha seja realmente necessária, mesmo que esteja um pouco frio lá fora!",
  str_homestory_N26dianying_90060201_23_dialog_content = "Em todo caso, estou aqui para ver um velho conhecido, então não precisarei de minha própria mesa.",
  str_homestory_N26dianying_90060201_23X1_dialog_content = "É uma pena que a loja ainda esteja em reforma... Não tem nem mesas nem cadeiras.",
  str_homestory_N26dianying_90060201_23X2_dialog_content = "Como você é o único convidado, pode comer em pé no balcão.",
  str_homestory_N26dianying_90060201_23X3_dialog_content = "Que? Você acha que eu posso alcançar o balcão!?",
  str_homestory_N26dianying_90060201_23X4_dialog_content = "Também não sei o que fazer. Tudo o que posso fazer é pedir-lhe para tentar ser mais alto.",
  str_homestory_N26dianying_90060201_23X5_dialog_content = "Você não acha que estou um pouco velho demais para continuar crescendo mais alto!?",
  str_homestory_N26dianying_90060201_23X6_dialog_content = "Além disso, realmente não há ninguém aqui! Estou no lugar certo?",
  str_homestory_N26dianying_90060201_23X7_dialog_content = "Droga! Procure por aqui novamente. Talvez haja outro Thorngate Inn.",
  str_homestory_N26dianying_90060201_23X8_dialog_content = "...",
  str_homestory_N26dianying_90060201_24_dialog_content = "Oh, eu vejo. Faça como quiser, então.",
  str_homestory_N26dianying_90060201_25_dialog_content = "Certo, agora vamos repassar a missão mais uma vez...",
  str_homestory_N26dianying_90060201_26_dialog_content = "\"Vá para a Estalagem Thorngate e faça contato com o misterioso guerreiro.\"",
  str_homestory_N26dianying_90060201_27_dialog_content = "\"O sigilo é de extrema importância, então o guerreiro escolheu manter sua identidade oculta.\"",
  str_homestory_N26dianying_90060201_28_dialog_content = "\"Apenas saiba que o guerreiro em questão está no auge de sua vida e que suas artes marciais são incomparáveis.\"",
  str_homestory_N26dianying_90060201_29_dialog_content = "\"Uma vez no Thorngate Inn, peça um pote de vinho osmanthus, e o guerreiro se aproximará de você.\"",
  str_homestory_N26dianying_90060201_30_dialog_content = "\"Depois de fazer contato, entregue a eles o elixir em sua posse, e o mundo estará em paz mais uma vez.\"",
  str_homestory_N26dianying_90060201_31_dialog_content = "\"Boa sorte, herói corajoso!\"",
  str_homestory_N26dianying_90060201_32_dialog_content = "Simples o suficiente! Eu só tenho que encontrar a pessoa certa, e minha busca está completa!",
  str_homestory_N26dianying_90060201_33_dialog_content = "Agora vamos ver qual dos convidados é o guerreiro que estou procurando...",
  str_homestory_N26dianying_90060201_34_dialog_content = "Oh! O-Ali!",
  str_homestory_N26dianying_90060201_35_dialog_content = "Vestido todo de preto, com uma atitude solene e reservada... Um mestre guerreiro tentando se manter discreto!",
  str_homestory_N26dianying_90060201_36_dialog_content = "Ela deve ser a pessoa que estou procurando! Agora para o próximo passo!",
  str_homestory_N26dianying_90060201_37_dialog_content = "Estalajadeiro! Um pote do seu melhor vinho osmanthus, por favor!",
  str_homestory_N26dianying_90060201_38_dialog_content = "Já está chegando! Vou deixar isso aqui para você.",
  str_homestory_N26dianying_90060201_39_dialog_content = "Poucas pessoas bebem isso hoje em dia, mas por favor, aproveite.",
  str_homestory_N26dianying_90060201_40_dialog_content = "Isso é perfeitamente bom. Algumas coisas devem ser mantidas em \"segredo\", certo?",
  str_homestory_N26dianying_90060201_41_dialog_content = "Perdoe-me, mas você gostaria de tomar uma bebida comigo?",
  str_homestory_N26dianying_90060201_42_dialog_content = "... Não. Agora vá embora.",
  str_homestory_N26dianying_90060201_43_dialog_content = "Mas é um pote de vinho osmanthus! Osmanthus! Poucas pessoas sabem disso, sabe?",
  str_homestory_N26dianying_90060201_44_dialog_content = "Além disso... Você parece o tipo de pessoa que gosta desse tipo de bebida! Direita? Direita???",
  str_homestory_N26dianying_90060201_45_dialog_content = "... Quem é você para me dizer minhas próprias preferências?",
  str_homestory_N26dianying_90060201_46_dialog_content = "Melhor ainda... Quem é você, afinal?",
  str_homestory_N26dianying_90060201_47_dialog_content = "Shh! Vou te contar, mas fala baixo...",
  str_homestory_N26dianying_90060201_48_dialog_content = "A verdade é que eu sei quem você realmente é...",
  str_homestory_N26dianying_90060201_49_dialog_content = "Você faz?!",
  str_homestory_N26dianying_90060201_50_dialog_content = "E-espere! Apenas mantenha a calma, ok?",
  str_homestory_N26dianying_90060201_51_dialog_content = "Se você sabe quem eu sou... Então não posso permitir que você viva.",
  str_homestory_N26dianying_90060201_52_dialog_content = "Que? Não! Quer dizer, eu sei que você está mantendo sua identidade em segredo! É porque sua busca é de extrema importância, lembra?",
  str_homestory_N26dianying_90060201_53_dialog_content = "Estou aqui para te ajudar!",
  str_homestory_N26dianying_90060201_54_dialog_content = "Ajude-me...?",
  str_homestory_N26dianying_90060201_55_dialog_content = "Com o quê, posso perguntar?",
  str_homestory_N26dianying_90060201_56_dialog_content = "Eu sei que suas artes marciais são inigualáveis no mundo, e que você está no auge de sua vida...",
  str_homestory_N26dianying_90060201_57_dialog_content = "Mas para proteger o mundo, há mais uma coisa que você precisa.",
  str_homestory_N26dianying_90060201_58_dialog_content = "... Do que diabos você está falando?",
  str_homestory_N26dianying_90060201_59_dialog_content = "O elixir, claro! Eu tenho aqui, só para você!",
  str_homestory_N26dianying_90060201_60_dialog_content = "R-Sério?!",
  str_homestory_N26dianying_90060201_61_dialog_content = "Isso poderia realmente estar acontecendo...?",
  str_homestory_N26dianying_90060201_62_dialog_content = "Isso mesmo! Desculpe se eu estava atrasado.",
  str_homestory_N26dianying_90060201_63_dialog_content = "Isso é bom! Basta entregá-lo já!",
  str_homestory_N26dianying_90060201_64_dialog_content = "Com este veneno, posso finalmente assassinar o governante da ilha e trazer a paz ao mundo mais uma vez!",
  str_homestory_N26dianying_90060201_65_dialog_content = "Com este veneno, posso finalmente assassinar o senhor da cidade e trazer a paz ao mundo mais uma vez!",
  str_homestory_N26dianying_90060201_66_dialog_content = "P-Veneno?!",
  str_homestory_N26dianying_90060201_67_dialog_content = "Como você já sabe quem eu sou, acho que não adianta guardar segredo.",
  str_homestory_N26dianying_90060201_68_dialog_content = "Seu palpite estava correto: eu sou o assassino de classe mundial que você estava procurando o tempo todo.",
  str_homestory_N26dianying_90060201_69_dialog_content = "E-espere... eu estava procurando por um assassino esse tempo todo?!",
  str_homestory_N26dianying_90060201_70_dialog_content = "Meus esforços para assassinar o governante da ilha foram infrutíferos até agora, mas com esse veneno...",
  str_homestory_N26dianying_90060201_71_dialog_content = "Meus esforços para assassinar o senhor da cidade foram infrutíferos até agora, mas com este veneno...",
  str_homestory_N26dianying_90060201_72_dialog_content = "Apresse-se e me dê!",
  str_homestory_N26dianying_90060201_73_dialog_content = "Não não não! Eu acredito que isso deve ser algum tipo de mal-entendido!",
  str_homestory_N26dianying_90060201_74_dialog_content = "Este elixir não é veneno de jeito nenhum! Além do mais...",
  str_homestory_N26dianying_90060201_75_dialog_content = "Não estamos em um país sem litoral? De que \"governante da ilha\" você está falando?!",
  str_homestory_N26dianying_90060201_76_dialog_content = "Agora que você mencionou isso, é um pouco estranho... Eu não vejo o mar em nenhum lugar por aqui!",
  str_homestory_N26dianying_90060201_77_dialog_content = "Claro que não! Estamos a milhares de quilômetros da praia mais próxima!",
  str_homestory_N26dianying_90060201_78_dialog_content = "As cerejeiras também são diferentes... Há até frutas crescendo nelas.",
  str_homestory_N26dianying_90060201_79_dialog_content = "Que \"árvores de cerejeira\"?! São pessegueiros!",
  str_homestory_N26dianying_90060201_80_dialog_content = "Não estamos em campo aberto? De que \"governante da cidade\" você está falando?!",
  str_homestory_N26dianying_90060201_81_dialog_content = "De onde diabos você veio?!",
  str_homestory_N26dianying_90060201_82_dialog_content = "Também não tenho certeza... Tudo o que sei é que devo executar meu assassinato do governante da ilha.",
  str_homestory_N26dianying_90060201_83_dialog_content = "Também não tenho certeza... Tudo o que sei é que devo executar meu assassinato do senhor da cidade.",
  str_homestory_N26dianying_90060201_84_dialog_content = "Então você deve pelo menos tentar estar no lugar certo!!",
  str_homestory_N26dianying_90060201_85_dialog_content = "Você sabe o que? Vamos fingir que essa conversa nunca aconteceu... Desculpe incomodá-lo.",
  str_homestory_N26dianying_90060201_86_dialog_content = "Além disso, tente ir para o leste da próxima vez... Você pode até ver o oceano algum dia.",
  str_homestory_N26dianying_90060201_87_dialog_content = "Além disso, tente ir para o leste da próxima vez... Você pode até encontrar a cidade que está procurando.",
  str_homestory_N26dianying_90060201_88_dialog_content = "Mas espere, o veneno...",
  str_homestory_N26dianying_90060201_89_dialog_content = "Apenas esqueça isso! Boa sorte com sua missão e bom dia!!",
  str_homestory_N26dianying_90060201_90_dialog_content = "Ugh... Onde diabos está essa pessoa que eu deveria encontrar?",
  str_homestory_N26dianying_90060201_91_dialog_content = "Eu estraguei tudo com aquela pessoa agora... Ela era misteriosa o suficiente, mas não havia nada de heroico nela. Acho que vou ter que tentar de novo...",
  str_homestory_N26dianying_90060201_92_dialog_content = "Ei... Essa pessoa parece bem heróica para mim!",
  str_homestory_N26dianying_90060201_93_dialog_content = "Estalajadeiro! Mais um pote de vinho osmanthus!",
  str_homestory_N26dianying_90060201_94_dialog_content = "Já está chegando! Vou deixar isso aqui para você.",
  str_homestory_N26dianying_90060201_95_dialog_content = "Não há como errar... Tem que ser a pessoa certa!",
  str_homestory_N26dianying_90060201_96_dialog_content = "Perdoe-me, mas você gostaria de tomar uma bebida comigo?",
  str_homestory_N26dianying_90060201_97_dialog_content = "Oh? Por todos os meios.",
  str_homestory_N26dianying_90060201_98_dialog_content = "Oh? Por todos os meios.",
  str_homestory_N26dianying_90060201_99_dialog_content = "Eu pedi um pote de vinho osmanthus! O estalajadeiro diz que seu sabor é único. Isso é... Algo que você gostaria?",
  str_homestory_N26dianying_90060201_100_dialog_content = "De uma vez só.",
  str_homestory_N26dianying_90060201_101_dialog_content = "Gosto disso? Eu amo isso!",
  str_homestory_N26dianying_90060201_102_dialog_content = "O que-?! Você bebeu tudo de uma só vez!!",
  str_homestory_N26dianying_90060201_103_dialog_content = "Para alguém gostar tanto de vinho de osmanthus... Deve ser ela a pessoa que procuro!",
  str_homestory_N26dianying_90060201_104_dialog_content = "Para alguém gostar tanto de vinho de osmanthus... Deve ser a pessoa que procuro!",
  str_homestory_N26dianying_90060201_105_dialog_content = "Ouça, herói, eu sei quem você realmente é. Você vê, eu...",
  str_homestory_N26dianying_90060201_106_dialog_content = "Shhh! Não tão alto!",
  str_homestory_N26dianying_90060201_107_dialog_content = "Oh, certo! Quase me esqueci... \"Sigilo máximo\" e tudo isso!",
  str_homestory_N26dianying_90060201_108_dialog_content = "Você veio fazer contato comigo, certo? Eu tenho esperado por tanto tempo...",
  str_homestory_N26dianying_90060201_109_dialog_content = "Hahahaha! Então você finalmente decidiu aparecer!",
  str_homestory_N26dianying_90060201_110_dialog_content = "Você veio fazer contato comigo, certo?",
  str_homestory_N26dianying_90060201_111_dialog_content = "Th-Isso mesmo! Desculpe por ser tão tarde!",
  str_homestory_N26dianying_90060201_112_dialog_content = "Pensar nada disso. Contanto que você deseje se tornar parte da minha tripulação, posso ignorá-lo pela primeira vez.",
  str_homestory_N26dianying_90060201_113_dialog_content = "Ah, não se preocupe com isso!",
  str_homestory_N26dianying_90060201_114_dialog_content = "Agora então... Bem-vindo a bordo, meu mais novo tripulante!",
  str_homestory_N26dianying_90060201_115_dialog_content = "C-Equipe?!",
  str_homestory_N26dianying_90060201_116_dialog_content = "De fato. E como você foi o primeiro a chegar, tem o privilégio de ser meu imediato.",
  str_homestory_N26dianying_90060201_117_dialog_content = "De agora em diante, você pode se referir a mim como \"capitão\".",
  str_homestory_N26dianying_90060201_118_dialog_content = "De fato. E como você foi o primeiro a chegar, tem o privilégio de ser meu imediato.",
  str_homestory_N26dianying_90060201_119_dialog_content = "De agora em diante, você pode se referir a mim como \"capitão\".",
  str_homestory_N26dianying_90060201_120_dialog_content = "Espere, espere, espere... Acho que houve algum tipo de mal-entendido de novo...",
  str_homestory_N26dianying_90060201_121_dialog_content = "Que tipo de capitão você é, exatamente? Estamos completamente sem litoral aqui, e não há um navio à vista por milhares de quilômetros!",
  str_homestory_N26dianying_90060201_122_dialog_content = "Você percebe isso também, então? Este lugar está sofrendo de uma grave falta de navios marítimos...",
  str_homestory_N26dianying_90060201_123_dialog_content = "Mas se eu conseguir construir um navio aqui, serei o primeiro capitão de toda a cidade! Uma honra de prestígio, você não concorda?",
  str_homestory_N26dianying_90060201_124_dialog_content = "Você percebe isso também, então? Este lugar está sofrendo de uma grave falta de navios marítimos...",
  str_homestory_N26dianying_90060201_125_dialog_content = "Mas se eu conseguir construir um navio aqui, serei o primeiro capitão de toda a cidade! Uma honra de prestígio, você não concorda?",
  str_homestory_N26dianying_90060201_126_dialog_content = "Bem, tanto quanto eu admiro seu espírito pioneiro...",
  str_homestory_N26dianying_90060201_127_dialog_content = "Você não acha que a falta de navios tem a ver, não sei... com a falta de um corpo d'água?!",
  str_homestory_N26dianying_90060201_128_dialog_content = "Heh... Um navio não PRECISA de água para navegar.",
  str_homestory_N26dianying_90060201_129_dialog_content = "Heh... Um navio não PRECISA de água para navegar.",
  str_homestory_N26dianying_90060201_130_dialog_content = "O que diabos isso quer dizer?!",
  str_homestory_N26dianying_90060201_131_dialog_content = "Fique tranquilo, levei todas essas perguntas em consideração.",
  str_homestory_N26dianying_90060201_132_dialog_content = "Fique tranquilo, levei todas essas perguntas em consideração.",
  str_homestory_N26dianying_90060201_133_dialog_content = "Sério? Porque eu discordo!",
  str_homestory_N26dianying_90060201_134_dialog_content = "Assim que pessoas suficientes se juntarem à nossa tripulação, podemos pedir o apoio do reino! Tudo vai dar certo quando chegarmos a esse ponto!",
  str_homestory_N26dianying_90060201_135_dialog_content = "Assim que pessoas suficientes se juntarem à nossa tripulação, podemos pedir o apoio do reino! Tudo vai dar certo quando chegarmos a esse ponto!",
  str_homestory_N26dianying_90060201_136_dialog_content = "... Você sabe o que? Acabei de lembrar que fico enjoado com muita facilidade! Além disso, tenho alguns outros negócios para resolver!",
  str_homestory_N26dianying_90060201_137_dialog_content = "já vou indo!",
  str_homestory_N26dianying_90060201_138_dialog_content = "Mas espere, que tal ser meu primeiro imediato?",
  str_homestory_N26dianying_90060201_139_dialog_content = "Mas espere, que tal ser meu primeiro imediato?",
  str_homestory_N26dianying_90060201_140_dialog_content = "Eu realmente não fui feito para a vida fanfarrão, eu juro! Boa sorte!",
  str_homestory_N26dianying_90060201_141_dialog_content = "Caramba... Existe ao menos uma única pessoa normal neste lugar?!",
  str_homestory_N26dianying_90060201_142_dialog_content = "Quem mais poderia ser...?",
  str_homestory_N26dianying_90060201_143_dialog_content = "Oh não... Há apenas uma pessoa que eu ainda não perguntei.",
  str_homestory_N26dianying_90060201_144_dialog_content = "Mas eles não correspondem em nada à descrição da missão... O que devo fazer?",
  str_homestory_N26dianying_90060201_145_dialog_content = "Ah, esquece... Já estou aqui, então posso tentar.",
  str_homestory_N26dianying_90060201_146_dialog_content = "Estalajadeiro! Mais um pote, por favor!",
  str_homestory_N26dianying_90060201_147_dialog_content = "Muito bem, mas... Você sabe que este é o seu terceiro pote, certo?",
  str_homestory_N26dianying_90060201_148_dialog_content = "Não fazia ideia de que gostavas tanto de vinho de osmanthus.",
  str_homestory_N26dianying_90060201_149_dialog_content = "P-Para ser honesto, eu nem tomei um gole disso...",
  str_homestory_N26dianying_90060201_150_dialog_content = "Por favor, deixe este cliente de aparência estranha ser a pessoa que estou procurando...",
  str_homestory_N26dianying_90060201_151_dialog_content = "Perdoe-me, mas você gostaria de...",
  str_homestory_N26dianying_90060201_152_dialog_content = "Você está finalmente aqui!",
  str_homestory_N26dianying_90060201_153_dialog_content = "Hã?!",
  str_homestory_N26dianying_90060201_154_dialog_content = "D-Desculpe, sua resposta meio que me pegou desprevenida...",
  str_homestory_N26dianying_90060201_155_dialog_content = "Você sabe quem eu sou, certo?",
  str_homestory_N26dianying_90060201_156_dialog_content = "Eu faço? Desculpe, mas não tenho mais certeza de nada...",
  str_homestory_N26dianying_90060201_157_dialog_content = "As duas últimas pessoas que abordei eram... outra coisa.",
  str_homestory_N26dianying_90060201_158_dialog_content = "Eu venho de mil anos no futuro!",
  str_homestory_N26dianying_90060201_159_dialog_content = "E você não é diferente!!!",
  str_homestory_N26dianying_90060201_160_dialog_content = "Fiquei preso neste ponto depois que um erro de entrada causou um mau funcionamento crítico do meu teletransportador.",
  str_homestory_N26dianying_90060201_161_dialog_content = "Mas você está aqui para me levar de volta, certo?",
  str_homestory_N26dianying_90060201_162_dialog_content = "... Não entendi uma única palavra que saiu da sua boca agora.",
  str_homestory_N26dianying_90060201_163_dialog_content = "Espere, então você NÃO vai me levar de volta ao meu tempo? Muito ruim.",
  str_homestory_N26dianying_90060201_164_dialog_content = "Aargh! Eu falhei completamente em minha busca!",
  str_homestory_N26dianying_90060201_165_dialog_content = "Busca?",
  str_homestory_N26dianying_90060201_166_dialog_content = "Busca? Que missão?",
  str_homestory_N26dianying_90060201_167_dialog_content = "Ah, esquece... Não importa mais.",
  str_homestory_N26dianying_90060201_168_dialog_content = "Desculpe, mas não sou a pessoa que você está procurando.",
  str_homestory_N26dianying_90060201_169_dialog_content = "Ainda assim, tenho que perguntar... O que alguém do futuro está fazendo em um lugar como este?",
  str_homestory_N26dianying_90060201_170_dialog_content = "Mil anos no futuro, meu laboratório está localizado neste mesmo local.",
  str_homestory_N26dianying_90060201_171_dialog_content = "Isso porque meu laboratório está neste exato lugar! Apenas mil anos no futuro, é claro.",
  str_homestory_N26dianying_90060201_172_dialog_content = "De qualquer forma, meus colegas pesquisadores devem estar aqui para me resgatar em breve... A qualquer minuto agora.",
  str_homestory_N26dianying_90060201_173_dialog_content = "Então é por isso que você está esperando aqui o tempo todo? Não há outra maneira de voltar ao seu tempo?",
  str_homestory_N26dianying_90060201_174_dialog_content = "Bem, eu poderia esperar mais mil anos?",
  str_homestory_N26dianying_90060201_175_dialog_content = "Na verdade, não. Não consigo entrar em contato com meus colegas a partir deste momento.",
  str_homestory_N26dianying_90060201_176_dialog_content = "Se eu não conseguir alcançá-los, terei que esperar até que o laboratório seja construído novamente.",
  str_homestory_N26dianying_90060201_177_dialog_content = "Você vai ficar sentado aqui por um milênio?!",
  str_homestory_N26dianying_90060201_178_dialog_content = "Se é isso que é preciso, então sim.",
  str_homestory_N26dianying_90060201_179_dialog_content = "Isso é, uh... Vai exigir muita paciência.",
  str_homestory_N26dianying_90060201_180_dialog_content = "Suspiro... Se ao menos meu herói tivesse esse tipo de paciência!",
  str_homestory_N26dianying_90060201_181_dialog_content = "Ainda assim, não os culpo por não estarem aqui. Se alguma coisa, é minha culpa por chegar tão tarde...",
  str_homestory_N26dianying_90060201_182_dialog_content = "Você sempre pode passar os próximos mil anos me fazendo companhia?",
  str_homestory_N26dianying_90060201_183_dialog_content = "Poxa, obrigado pela gentil oferta...",
  str_homestory_N26dianying_90060201_184_dialog_content = "Eu só queria poder ser tão otimista sobre as coisas quanto você...",
  str_homestory_N26dianying_90060201_185_dialog_content = "Ei! Ouçam, seus porcos complacentes!",
  str_homestory_N26dianying_90060201_186_dialog_content = "Huh? O que há com toda a gritaria lá fora?",
  str_homestory_N26dianying_90060201_187_dialog_content = "Esta montanha pertence a mim, ouviu?",
  str_homestory_N26dianying_90060201_188_dialog_content = "Se você tem algum cérebro entre as orelhas, deixe seus objetos de valor para trás e se perca! Se você não fizer isso, eu vou quebrar todos os pequenos cérebros que você tem no chão!",
  str_homestory_N26dianying_90060201_189_dialog_content = "Bandidos?! Ah, isso é ruim!",
  str_homestory_N26dianying_90060201_190_dialog_content = "Eu não sou páreo para todos eles de uma vez! Tenho que dar um jeito de sair daqui...",
  str_homestory_N26dianying_90060201_191_dialog_content = "Droga... Se eu lutar contra eles, meu disfarce será descoberto. Hora de recuar...",
  str_homestory_N26dianying_90060201_192_dialog_content = "Isso foi rápido!!",
  str_homestory_N26dianying_90060201_193_dialog_content = "Ótimo! Basta olhar para todos aqueles rostos ansiosos! Eles devem ter vindo para se juntar à minha tripulação!",
  str_homestory_N26dianying_90060201_194_dialog_content = "Eu deveria ir cumprimentá-los!",
  str_homestory_N26dianying_90060201_195_dialog_content = "Ótimo! Basta olhar para todos aqueles rostos ansiosos! Eles devem ter vindo para se juntar à minha tripulação!",
  str_homestory_N26dianying_90060201_196_dialog_content = "Eu deveria ir cumprimentá-los!",
  str_homestory_N26dianying_90060201_197_dialog_content = "G-Volte aqui! Você não tem o menor controle sobre a realidade?!",
  str_homestory_N26dianying_90060201_198_dialog_content = "Isso não vai adiantar... Não posso deixar uma horda de bandidos tomar conta do futuro local do laboratório.",
  str_homestory_N26dianying_90060201_199_dialog_content = "Eu irei exterminá-los.",
  str_homestory_N26dianying_90060201_200_dialog_content = "Por você mesmo? Mas parece que há um monte deles por aí!",
  str_homestory_N26dianying_90060201_201_dialog_content = "Uau... Simples assim, os únicos que sobraram aqui são o estalajadeiro e eu...",
  str_homestory_N26dianying_90060201_202_dialog_content = "Este não é o meu dia... Primeiro não consigo fazer contato com a pessoa certa, então somos atacados por bandidos...",
  str_homestory_N26dianying_90060201_203_dialog_content = "Ainda preciso pagar minha conta se todos acabarmos mortos?",
  str_homestory_N26dianying_90060201_204_dialog_content = "Então você desistiu de sua busca, não é?",
  str_homestory_N26dianying_90060201_205_dialog_content = "Sim... suponho que seja hora de aceitar meu destino...",
  str_homestory_N26dianying_90060201_206_dialog_content = "E-espere, como você sabe disso?!",
  str_homestory_N26dianying_90060201_207_dialog_content = "Minha busca deveria ser ultrassecreta!",
  str_homestory_N26dianying_90060201_208_dialog_content = "A pessoa que você procurava estava aqui o tempo todo...",
  str_homestory_N26dianying_90060201_209_dialog_content = "Mas isso não os tornava necessariamente clientes.",
  str_homestory_N26dianying_90060201_210_dialog_content = "Espere, você não quer dizer...",
  str_homestory_N26dianying_90060201_211_dialog_content = "Poderia ser...?!",
  str_homestory_N26dianying_90060201_212_dialog_content = "VOCÊ é o guerreiro que eu deveria conhecer?!",
  str_homestory_N26dianying_90060201_213_dialog_content = "De jeito nenhum! Isso não pode ser!",
  str_homestory_N26dianying_90060201_214_dialog_content = "A pessoa na busca deve estar \"no auge de sua vida\"! Suas artes marciais devem ser inigualáveis! Mas você...",
  str_homestory_N26dianying_90060201_215_dialog_content = "Seu rosto está tão desgastado... E você está confinado a uma cadeira de rodas! Como você pode ser a pessoa que estou procurando?!",
  str_homestory_N26dianying_90060201_216_dialog_content = "Heh, uma descrição bastante fantasiosa... Mas se encaixa, mesmo assim. O guerreiro que você veio aqui para encontrar não é outro senão o seu verdadeiramente.",
  str_homestory_N26dianying_90060201_217_dialog_content = "Apenas... Você chegou tarde demais.",
  str_homestory_N26dianying_90060201_218_dialog_content = "Dez anos atrasado, na verdade!",
  str_homestory_N26dianying_90060201_219_dialog_content = "Dez anos?!",
  str_homestory_N26dianying_90060201_220_dialog_content = "O que?!?",
  str_homestory_N26dianying_90060201_221_dialog_content = "Minhas pernas ficaram gravemente feridas dez anos atrás, então me escondi aqui. Estou esperando que um herói me traga um elixir de cura.",
  str_homestory_N26dianying_90060201_222_dialog_content = "Mas não importa quanto tempo eu esperei... Aquele herói nunca apareceu.",
  str_homestory_N26dianying_90060201_223_dialog_content = "Muita coisa mudou nos últimos dez anos. Obriguei-me a beber vinho de osmanthus todos os dias e, eventualmente, desenvolvi um gosto por ele.",
  str_homestory_N26dianying_90060201_224_dialog_content = "Como o elixir nunca veio, minhas pernas pioraram gradualmente e acabei em uma cadeira de rodas.",
  str_homestory_N26dianying_90060201_225_dialog_content = "Tornei-me amigo íntimo do proprietário anterior desta pousada e, quando ele finalmente faleceu... Fiquei surpreso ao saber que ele a havia confiado a mim.",
  str_homestory_N26dianying_90060201_226_dialog_content = "Nunca esperei que, depois de todo esse tempo, você ainda aparecesse.",
  str_homestory_N26dianying_90060201_227_dialog_content = "Ah, uh...",
  str_homestory_N26dianying_90060201_228_option_content = "Peça desculpas sinceramente",
  str_homestory_N26dianying_90060201_229_dialog_content = "Não fique aí parado! Peça desculpas, agora mesmo!",
  str_homestory_N26dianying_90060201_230_dialog_content = "F-Perdoe-me, bravo herói! Do fundo do meu coração, sinto muito!",
  str_homestory_N26dianying_90060201_231_dialog_content = "E-Se ao menos eu não estivesse tão atrasado...",
  str_homestory_N26dianying_90060201_232_dialog_content = "Você estava dez anos \"atrasado\"? Você não acha que isso é um pouco de eufemismo?",
  str_homestory_N26dianying_90060201_233_dialog_content = "É tudo minha culpa... Perdi o pergaminho da missão em algum lugar da minha casa...",
  str_homestory_N26dianying_90060201_234_dialog_content = "Foi só quando comecei a fazer as malas para me mudar que finalmente o encontrei. O único problema foi que eu esqueci quantos anos o pedido realmente tinha...",
  str_homestory_N26dianying_90060201_235_dialog_content = "Está bem. Se isso tivesse acontecido alguns anos atrás, eu poderia ter ficado chateado, mas agora... não posso deixar de achar divertido. Risível, até.",
  str_homestory_N26dianying_90060201_236_dialog_content = "Você parece ser completamente sincero, então não vou insistir no assunto. Meus dias de aventura ficaram para trás; Eu só desejo passar o resto da minha vida em paz.",
  str_homestory_N26dianying_90060201_237_dialog_content = "Ainda assim, deixei alguns assuntos inacabados no passado... Se você realmente deseja fazer as pazes, poderia cuidar deles em meu lugar?",
  str_homestory_N26dianying_90060201_238_dialog_content = "Sério? Claro, eu estaria mais do que disposto a ajudar!",
  str_homestory_N26dianying_90060201_239_dialog_content = "Um antigo parceiro meu dos meus dias de aventura mora perto. Assim como eu, ele optou por manter sua identidade oculta e trabalha no mercado.",
  str_homestory_N26dianying_90060201_240_dialog_content = "Tenho uma carta para ele e quero que você cumpra minha missão entregando-a a ele.",
  str_homestory_N26dianying_90060201_241_dialog_content = "Entendido! Eu só tenho que me encontrar com outro contato anônimo, certo? Eu definitivamente tenho experiência com esse tipo de busca agora!",
  str_homestory_N26dianying_90060201_242_dialog_content = "Eu certamente espero que sim.",
  str_homestory_N26dianying_90060201_243_dialog_content = "Não há mais espaço para o seu \"atraso\" quando se trata de entregar esta carta.",
  str_homestory_N26dianying_90060201_244_dialog_content = "A pessoa em questão é ainda mais velha do que eu. Duvido que ele viva para ver outra década passar.",
  str_homestory_N26dianying_90060201_245_option_content = "Invente uma desculpa",
  str_homestory_N26dianying_90060201_246_dialog_content = "Você esqueceu? Pense no motivo pelo qual você chegou tão atrasado!",
  str_homestory_N26dianying_90060201_247_dialog_content = "Oh, certo! É porque eu tinha muitas missões em minhas mãos!",
  str_homestory_N26dianying_90060201_248_dialog_content = "Você vê, com a terra em tal estado de desordem, eu tinha tantos heróis me alcançando que eu não conseguia acompanhar todos eles!",
  str_homestory_N26dianying_90060201_249_dialog_content = "Alguns deles já estavam à beira da morte, então tive que priorizá-los.",
  str_homestory_N26dianying_90060201_250_dialog_content = "U-Infelizmente... Por isso demorei tanto para vir te encontrar.",
  str_homestory_N26dianying_90060201_251_dialog_content = "É assim mesmo? Eu não tinha ideia de que havia tantos heróis em perigo...",
  str_homestory_N26dianying_90060201_252_dialog_content = "Por que você não nomeia alguns deles para mim? Quem sabe, talvez eu os conhecesse na minha época?",
  str_homestory_N26dianying_90060201_253_dialog_content = "Eu me sentiria muito melhor sabendo que meus antigos camaradas foram cuidados, mesmo que fosse às minhas próprias custas.",
  str_homestory_N26dianying_90060201_254_dialog_content = "S-Claro, só um momento...",
  str_homestory_N26dianying_90060201_255_dialog_content = "Leve o tempo que precisar. Afinal, esperei dez anos por você... Poderia esperar mais dez.",
  str_homestory_N26dianying_90060201_256_dialog_content = "Se você não consegue se lembrar de seus nomes, talvez eu possa apresentá-lo a alguns deles? Isso pode refrescar sua memória...",
  str_homestory_N26dianying_90060201_257_dialog_content = "I-Apresentar-me a eles?",
  str_homestory_N26dianying_90060201_258_dialog_content = "Isso mesmo, embora eu não deva mais chamá-los de \"heróis\". Veja, alguns deles começaram a seguir o caminho errado no passado...",
  str_homestory_N26dianying_90060201_259_dialog_content = "Na verdade, acredito que alguns deles estão do lado de fora da minha porta, esperando uma chance de falar sobre os bons velhos tempos.",
  str_homestory_N26dianying_90060201_260_dialog_content = "Você não quer dizer os bandidos... Quer dizer?!",
  str_homestory_N26dianying_90060201_261_dialog_content = "Não por favor! Eu não quero conhecê-los!",
  str_homestory_N26dianying_90060201_262_dialog_content = "Eu estava errado, Sr. Estalajadeiro! Eu sinto Muito!!!",
  str_homestory_N26dianying_90060201_263_option_content = "Complete a missão",
  str_homestory_N26dianying_90060201_264_dialog_content = "Não se esqueça! Você ainda tem uma missão para completar!",
  str_homestory_N26dianying_90060201_265_dialog_content = "Nada disso importa agora! Eu trouxe o elixir que você pediu, bravo herói!",
  str_homestory_N26dianying_90060201_266_dialog_content = "E enquanto eu estava um pouco atrasada com a entrega... Minha missão finalmente está completa!",
  str_homestory_N26dianying_90060201_267_dialog_content = "\"Um pouco tarde\", você diz?",
  str_homestory_N26dianying_90060201_268_dialog_content = "Eu não tinha ideia de que uma década era uma quantidade tão insignificante de tempo...",
  str_homestory_N26dianying_90060201_269_dialog_content = "Eu sinto muito por isso... É só que eu perdi o pergaminho de missão em algum lugar da minha casa...",
  str_homestory_N26dianying_90060201_270_dialog_content = "Foi só quando comecei a fazer as malas para me mudar que finalmente o encontrei. O único problema foi que eu esqueci quantos anos o pedido realmente tinha...",
  str_homestory_N26dianying_90060201_271_dialog_content = "De qualquer forma, eu trouxe tudo para cá, então aqui está. Quem sabe, pode apenas consertar suas pernas!",
  str_homestory_N26dianying_90060201_272_dialog_content = "Dessa forma, posso entregar minha missão quando voltar.",
  str_homestory_N26dianying_90060201_273_dialog_content = "Não preciso mais disso. Minhas pernas estão acabadas e nenhuma quantidade de elixir poderia consertá-las.",
  str_homestory_N26dianying_90060201_274_dialog_content = "Apenas guarde para você. Você pode acabar precisando algum dia.",
  str_homestory_N26dianying_90060201_275_dialog_content = "Eu não sei sobre isso... Além disso, não posso entregar minha missão se você não pegá-la.",
  str_homestory_N26dianying_90060201_276_dialog_content = "Bem, nós estamos cercados por um grupo de bandidos sedentos de sangue...",
  str_homestory_N26dianying_90060201_277_dialog_content = "Acho que você pode precisar mais do que pensa muito em breve.",
  str_homestory_N26dianying_90060201_278_dialog_content = "O que?!?",
  str_homestory_N26dianying_90060201_279_dialog_content = "Não por favor! Salve-me, grande e misericordioso herói!",
  str_homestory_N26dianying_90060201_280_dialog_content = "Estalajadeiro! Um pote do seu melhor vinho osmanthus, por favor!",
  str_homestory_N26dianying_90060201_281_dialog_content = "Desculpe, mas estamos todos fora.",
  str_homestory_N26dianying_90060201_282_dialog_content = "Que? \"Tudo fora\"?!",
  str_homestory_N26dianying_90060201_283_dialog_content = "Isso mesmo. Não tenho uma gota do material disponível no momento.",
  str_homestory_N26dianying_90060201_284_dialog_content = "Como você pode fugir em um momento como este? Tudo está arruinado agora!",
  str_homestory_N26dianying_90060201_285_dialog_content = "Eu sempre posso mandar buscar, se você quiser?",
  str_homestory_N26dianying_90060201_286_dialog_content = "Se você está tão empenhado em ter esse tipo de vinho hoje, posso pedir um pouco de uma loja vizinha. Levará algum tempo, mas pode ser feito.",
  str_homestory_N26dianying_90060201_287_dialog_content = "S-Sério?",
  str_homestory_N26dianying_90060201_288_dialog_content = "Tudo bem, posso esperar!",
  str_homestory_N26dianying_90060201_289_dialog_content = "Este vinho osmanthus tem um sabor único. Poucas pessoas bebem isso hoje em dia, mas por favor, aproveite.",
  str_homestory_N26dianying_90060201_290_dialog_content = "Ainda assim, faz bem ao meu coração ver alguém que aprecia minha bebida favorita.",
  str_homestory_N26dianying_90060201_291_dialog_content = "Apenas coloque-o de lado quando chegar aqui, por favor. Tudo ficará arruinado se eu não tiver um pote disso...",
  str_homestory_N26dianying_90060201_292_dialog_content = "<color=#e8d9bb>Bata, bate, bate!</color>",
  str_homestory_N26dianying_90060201_293_dialog_content = "Alguém está na porta! Eles trouxeram o vinho osmanthus?",
  str_homestory_N26dianying_90060201_294_dialog_content = "Shhh! Aquela voz...",
  str_homestory_N26dianying_90060201_295_dialog_content = "Ei! Ouçam, seus porcos complacentes!",
  str_homestory_N26dianying_90060201_296_dialog_content = "Esta montanha pertence a mim, ouviu?",
  str_homestory_N26dianying_90060201_297_dialog_content = "Se você tem algum cérebro entre as orelhas, deixe seus objetos de valor para trás e se perca! Se você não fizer isso, eu vou quebrar todos os pequenos cérebros que você tem no chão!",
  str_homestory_N26dianying_90060201_298_dialog_content = "Bandidos? Agora, de todos os tempos?!",
  str_homestory_N26dianying_90060201_299_dialog_content = "Droga... Se eu lutar contra eles, meu disfarce será descoberto. Hora de recuar...",
  str_homestory_N26dianying_90060201_300_dialog_content = "Ótimo! Eu irei cumprimentá-los!",
  str_homestory_N26dianying_90060201_301_dialog_content = "Ótimo! Eu irei cumprimentá-los!",
  str_homestory_N26dianying_90060201_302_dialog_content = "Extermine todos eles.",
  str_homestory_N26dianying_90060201_303_dialog_content = "Infelizmente, parece que minha humilde pousada está prestes a ser saqueada por uma gangue de bandidos.",
  str_homestory_N26dianying_90060201_304_dialog_content = "Agora então, se você puder fazer a gentileza de escapar pelos fundos...",
  str_homestory_N26dianying_90060201_305_dialog_content = "Bem, eu adoraria escapar com vida e tudo...",
  str_homestory_N26dianying_90060201_306_dialog_content = "Mas e a minha busca?!",
  str_homestory_N26dianying_90060301_1_dialog_content = "As chamas da guerra devastaram nosso mundo por muitos anos... A cada dia que passa, nossa luta contra os Eclipsitas parece cada vez mais sem esperança.",
  str_homestory_N26dianying_90060301_2_dialog_content = "Apenas a há muito perdida Lâmina Celestial, uma arma sagrada e poderosa, pode acabar com o conflito e trazer a paz ao mundo mais uma vez.",
  str_homestory_N26dianying_90060301_3_dialog_content = "... Ou assim diz a lenda. Não é verdade, meu fiel servo?",
  str_homestory_N26dianying_90060301_4_dialog_content = "<size=45>Sim, meu senhor!</size>",
  str_homestory_N26dianying_90060301_5_dialog_content = "Argh, meus ouvidos! Fale baixo, tolo!",
  str_homestory_N26dianying_90060301_6_dialog_content = "Ahem... Como enviado do Dragonscorch, a força mais poderosa da terra, tenho meus motivos para convocá-lo aqui hoje.",
  str_homestory_N26dianying_90060301_7_dialog_content = "Apesar de ter se juntado recentemente à nossa facção, você já provou ser um servo leal e capaz.",
  str_homestory_N26dianying_90060301_8_dialog_content = "Pois bem, a lenda também diz que a Lâmina Celestial foi vista pela última vez na Vila dos Dragões. Pelo que entendi, você também é da mesma aldeia, não é?",
  str_homestory_N26dianying_90060301_9_dialog_content = "<size=45>Sim, meu senhor!</size>",
  str_homestory_N26dianying_90060301_10_dialog_content = "Excelente... Então, por meio deste, confio a você um dever sagrado: retorne à Vila dos Dragões e encontre a Lâmina Celestial em meu lugar.",
  str_homestory_N26dianying_90060301_11_dialog_content = "Tenha certeza, meu senhor, não vou falhar com você!",
  str_homestory_N26dianying_90060301_12_dialog_content = "Agora são 11:15 da manhã... Começando agora, você tem exatamente três dias para encontrar a lâmina e trazê-la para mim.",
  str_homestory_N26dianying_90060301_13_dialog_content = "(Espera... Ele disse \"11:15\"?!)",
  str_homestory_N26dianying_90060301_14_dialog_content = "Er, meu senhor? Eu, uh... Acabei de perceber que ainda preciso empacotar alguns suprimentos antes de partir em minha nobre missão!",
  str_homestory_N26dianying_90060301_15_dialog_content = "Muito bem, então. Veja seus suprimentos e siga seu caminho, mas seja rápido!",
  str_homestory_N26dianying_90060301_16_dialog_content = "Suspiro, suspiro, suspiro...",
  str_homestory_N26dianying_90060301_17_dialog_content = "M-Mestre! Peço desculpas pelo pequeno atraso!",
  str_homestory_N26dianying_90060301_18_dialog_content = "\"Leve\", você diz? Você está trinta minutos atrasado.",
  str_homestory_N26dianying_90060301_19_dialog_content = "Suspiro... Não importa. Convoquei você hoje porque preciso de sua ajuda para um assunto da maior importância.",
  str_homestory_N26dianying_90060301_20_dialog_content = "Certamente, você já ouviu a lenda da Lâmina Celestial? \"As chamas da guerra devastaram nosso mundo por muitos anos...\"",
  str_homestory_N26dianying_90060301_21_dialog_content = "Meu senhor, será que... Você também deseja que eu vá até a Vila dos Dragões em busca da Lâmina Celestial?",
  str_homestory_N26dianying_90060301_22_dialog_content = "Está correto. Ao encontrar a Lâmina Celestial, a Facção Zakura trará ordem a este mundo caótico e solidificará seu lugar como a força mais poderosa que existe.",
  str_homestory_N26dianying_90060301_23_dialog_content = "Espere... O que quer dizer com \"também\"?",
  str_homestory_N26dianying_90060301_24_dialog_content = "Oh! N-Nada, meu senhor!",
  str_homestory_N26dianying_90060301_25_dialog_content = "(Se os enviados de ambas as facções descobrirem que estou cumprindo a mesma missão para eles...)",
  str_homestory_N26dianying_90060301_26_dialog_content = "(Eu estarei tão bom quanto morto!)",
  str_homestory_N26dianying_90060301_27_dialog_content = "Enquanto você ainda não tem experiência, minhas fontes me dizem que a lâmina pode ser encontrada em algum lugar em sua cidade natal, a Vila dos Dragões. Você é a única pessoa em quem posso confiar nesta missão.",
  str_homestory_N26dianying_90060301_28_dialog_content = "<size=45>Sim, meu senhor!</size>",
  str_homestory_N26dianying_90060301_29_dialog_content = "H-No entanto, ainda tenho algumas coisas para discutir com meus camaradas antes de partir...",
  str_homestory_N26dianying_90060301_30_dialog_content = "Muito bem, mas tente ser breve. Ah, e lembre-se de verificar o tempo para mim antes de sair.",
  str_homestory_N26dianying_90060301_31_dialog_content = "Suspiro, suspiro, suspiro...",
  str_homestory_N26dianying_90060301_32_dialog_content = "M-Meu senhor! O tempo hoje está bom, um dia perfeito para treinar seus soldados!",
  str_homestory_N26dianying_90060301_33_dialog_content = "Hum? Não me lembro de ter pedido uma previsão do tempo?",
  str_homestory_N26dianying_90060301_34_dialog_content = "(Oh, merda! Senhor errado!)",
  str_homestory_N26dianying_90060301_35_dialog_content = "Se você terminou seus preparativos, saia imediatamente! Se você tiver sucesso, suas recompensas serão abundantes!",
  str_homestory_N26dianying_90060301_36_dialog_content = "Ah, e se você vir os girassóis florescendo durante sua jornada, encontre uma maneira de me avisar. Entendido?",
  str_homestory_N26dianying_90060301_37_dialog_content = "Sim, meu senhor! Vou embora imediatamente!",
  str_homestory_N26dianying_90060301_38_dialog_content = "Suspiro, suspiro, suspiro...",
  str_homestory_N26dianying_90060301_39_dialog_content = "Estou de volta, meu senhor! Os girassóis estão floridos e cheios de sementes! Eles podem ser colhidos a qualquer momento para as rações dos soldados!",
  str_homestory_N26dianying_90060301_40_dialog_content = "Hum? E quando exatamente eu pedi um relatório sobre os girassóis?",
  str_homestory_N26dianying_90060301_41_dialog_content = "Ah, e durante sua jornada, se você notar que os juncos cresceram, encontre uma maneira de me avisar. Entendido?",
  str_homestory_N26dianying_90060301_42_dialog_content = "Sim, meu senhor! Vou embora imediatamente!",
  str_homestory_N26dianying_90060301_43_dialog_content = "Suspiro, suspiro, suspiro...",
  str_homestory_N26dianying_90060301_44_dialog_content = "Estou de volta, meu senhor! Os juncos são altos e densos agora, perfeitos para esconder um ataque surpresa contra seus inimigos!",
  str_homestory_N26dianying_90060301_45_dialog_content = "Oh? E quando exatamente eu pedi um relatório sobre os juncos?",
  str_homestory_N26dianying_90060301_46_dialog_content = "Ah, e durante sua jornada, se você perceber que os campos de trigo atingiram a maturidade total, encontre uma maneira de me avisar. Entendido?",
  str_homestory_N26dianying_90060301_47_dialog_content = "Sim, meu senhor! Vou embora imediatamente!",
  str_homestory_N26dianying_90060301_48_dialog_content = "Suspiro, suspiro, suspiro...",
  str_homestory_N26dianying_90060301_49_dialog_content = "Estou de volta, meu senhor! Os campos de trigo estão cheios e prontos para a colheita! Os soldados vão comer bem neste inverno!",
  str_homestory_N26dianying_90060301_50_dialog_content = "Oh? E quando exatamente eu pedi um relatório sobre os campos de trigo?",
  str_homestory_N26dianying_90060301_50X1_dialog_content = "Ah, e durante a viagem, se notar alguma pessoa suspeita, dê um jeito de me avisar. Entendido?",
  str_homestory_N26dianying_90060301_50X2_dialog_content = "Sim, meu senhor! Vou embora imediatamente!",
  str_homestory_N26dianying_90060301_50X3_dialog_content = "Suspiro, suspiro, suspiro...",
  str_homestory_N26dianying_90060301_50X4_dialog_content = "Estou de volta, meu senhor! Não há pessoas suspeitas por perto. Podemos começar a nos preparar para o treinamento!",
  str_homestory_N26dianying_90060301_50X5_dialog_content = "Hum? Não me lembro de ter pedido para você relatar a situação próxima para mim!",
  str_homestory_N26dianying_90060301_51_dialog_content = "(Merda! De novo não!!)",
  str_homestory_N26dianying_90060301_52_dialog_content = "Se você terminou de se despedir de seus amigos, corra para a Vila dos Dragões. Você terá minha eterna gratidão caso tenha sucesso em sua busca.",
  str_homestory_N26dianying_90060301_53_dialog_content = "Sim, meu senhor! Vou embora imediatamente!",
  str_homestory_N26dianying_90060301_54_dialog_content = "(Meus senhores, vocês são homens sábios e poderosos... Então, por favor, perdoem-me!)",
  str_homestory_N26dianying_90060301_55_dialog_content = "(Duas recompensas pelo preço de uma missão... É bom demais para deixar passar!)",
  str_homestory_N26dianying_90060301_56_dialog_content = "Ufa... Finalmente cheguei à Vila dos Dragões. Isso realmente me leva de volta...",
  str_homestory_N26dianying_90060301_57_dialog_content = "Dê um passo à direita e dê uma olhada! Armas maravilhosas de todo o mundo! Espadas e lâminas sagradas em abundância, tudo com descontos de cair o queixo!",
  str_homestory_N26dianying_90060301_58_dialog_content = "Venha um, venha todos! Tenho todos os tipos de espadas sagradas à venda aqui, mas minhas conchas de água benta são as verdadeiras estrelas do show!",
  str_homestory_N26dianying_90060301_59_dialog_content = "Que? Desculpe, você disse que tem espadas sagradas à venda?",
  str_homestory_N26dianying_90060301_60_dialog_content = "Se é isso que você está procurando, então você veio ao lugar certo! Caramba, eu até tenho a Lâmina Celestial em estoque, se você estiver interessado?",
  str_homestory_N26dianying_90060301_61_dialog_content = "Está vendo aquela espada no suporte de armas ali? Eu estaria disposto a me desfazer dele pelo preço baixíssimo de 99.999.999 Nightium!",
  str_homestory_N26dianying_90060301_62_dialog_content = "Se é isso que você está procurando, então você veio ao lugar certo! Caramba, eu até tenho a Lâmina Celestial em estoque, se você estiver interessado?",
  str_homestory_N26dianying_90060301_63_dialog_content = "Está vendo aquela espada no suporte de armas ali? Eu estaria disposto a me desfazer dele pelo preço baixíssimo de 99.999.999 Nightium!",
  str_homestory_N26dianying_90060301_64_dialog_content = "Isso é tão caro! Poderia realmente ser a Lâmina Celestial das lendas...?",
  str_homestory_N26dianying_90060301_65_dialog_content = "Heheheh... Nada mal, hein? Você tem olho para a qualidade, senhorita!",
  str_homestory_N26dianying_90060301_66_dialog_content = "Bastante impressionante, hein? Você tem olho para a qualidade, senhorita!",
  str_homestory_N26dianying_90060301_67_dialog_content = "Esta não é a Lâmina Celestial.",
  str_homestory_N26dianying_90060301_68_dialog_content = "Huh? C-Como você sabia?!",
  str_homestory_N26dianying_90060301_69_dialog_content = "Huh? C-Como você sabia?!",
  str_homestory_N26dianying_90060301_70_dialog_content = "Eu não posso dizer com certeza como eu sei... Chame de intuição, eu acho?",
  str_homestory_N26dianying_90060301_71_dialog_content = "Ahem... Bem, você está certo! Essa espada não é a Lâmina Celestial, porque a verdadeira...",
  str_homestory_N26dianying_90060301_72_dialog_content = "A espada está bem ao lado dela!",
  str_homestory_N26dianying_90060301_73_dialog_content = "Ahem... Bem, você está certo! Essa espada não é a Lâmina Celestial, porque a verdadeira...",
  str_homestory_N26dianying_90060301_74_dialog_content = "A espada está bem ao lado dela!",
  str_homestory_N26dianying_90060301_75_dialog_content = "Sério? Deixe-me ver! ...Uh, perdoe-me, mas este também não é real!",
  str_homestory_N26dianying_90060301_76_dialog_content = "(Droga... Não tem como enganar ela!)",
  str_homestory_N26dianying_90060301_77_dialog_content = "(Droga... Não tem como enganar ela!)",
  str_homestory_N26dianying_90060301_78_dialog_content = "Tenho certeza que você já sabe, mas aqui na Vila dos Dragões não tentamos enganar nosso próprio povo. Agora, você poderia me dizer onde posso encontrar a verdadeira Lâmina Celestial?",
  str_homestory_N26dianying_90060301_79_dialog_content = "Tudo bem, você venceu... Aqui está.",
  str_homestory_N26dianying_90060301_80_dialog_content = "Tudo bem, você venceu... Aqui está.",
  str_homestory_N26dianying_90060301_81_dialog_content = "Uma fita de vídeo?!",
  str_homestory_N26dianying_90060301_82_dialog_content = "Vá colocar esta fita naquele projetor ali, e clique em \"play\".",
  str_homestory_N26dianying_90060301_83_dialog_content = "O projetor mostrará as respostas que você procura!",
  str_homestory_N26dianying_90060301_84_dialog_content = "Vá colocar esta fita naquele projetor ali, e clique em \"play\".",
  str_homestory_N26dianying_90060301_85_dialog_content = "O projetor mostrará as respostas que você procura!",
  str_homestory_N26dianying_90060301_86_dialog_content = "Hmm... Ele deve começar a tocar quando eu apertar este botão, certo?",
  str_homestory_N26dianying_90060301_87_dialog_content = "... Huh? Por que a imagem na fita não está se movendo? Também não tem som...",
  str_homestory_N26dianying_90060301_88_dialog_content = "Espere, está começando a se mover!!",
  str_homestory_N26dianying_90060301_89_dialog_content = "Tudo bem, você venceu... Aqui está.",
  str_homestory_N26dianying_90060301_90_dialog_content = "Tudo bem, você venceu... Aqui está.",
  str_homestory_N26dianying_90060301_91_dialog_content = "... Um mapa?!",
  str_homestory_N26dianying_90060301_92_dialog_content = "Pegue este mapa e siga-o até o local marcado.",
  str_homestory_N26dianying_90060301_93_dialog_content = "O mapa mostrará as respostas que você procura!",
  str_homestory_N26dianying_90060301_94_dialog_content = "Pegue este mapa e siga-o até o local marcado.",
  str_homestory_N26dianying_90060301_95_dialog_content = "O mapa mostrará as respostas que você procura!",
  str_homestory_N26dianying_90060301_96_dialog_content = "Hmm... Tenho certeza que segui o caminho certo, não?",
  str_homestory_N26dianying_90060301_97_dialog_content = "Ainda assim, mal consigo entender este mapa... A escrita nele é quase ilegível também...",
  str_homestory_N26dianying_90060301_98_dialog_content = "Hmm... Preciso dar uma olhada nisso!",
  str_homestory_N26dianying_90060301_99_dialog_content = "Tudo bem, você venceu... Olhe ali.",
  str_homestory_N26dianying_90060301_100_dialog_content = "Tudo bem, você venceu... Olhe ali.",
  str_homestory_N26dianying_90060301_101_dialog_content = "Uma caixa de correio?!",
  str_homestory_N26dianying_90060301_102_dialog_content = "Vá ler o que o proprietário anterior escreveu nele.",
  str_homestory_N26dianying_90060301_103_dialog_content = "A caixa de correio mostrará as respostas que você procura!",
  str_homestory_N26dianying_90060301_104_dialog_content = "Vá ler o que o proprietário anterior escreveu nele.",
  str_homestory_N26dianying_90060301_105_dialog_content = "A caixa de correio mostrará as respostas que você procura!",
  str_homestory_N26dianying_90060301_106_dialog_content = "Hmm... Essa caixa de correio é bem alta, hein?",
  str_homestory_N26dianying_90060301_107_dialog_content = "Mas mesmo daqui de baixo, posso dizer que a escrita é quase desleixada demais para ler...",
  str_homestory_N26dianying_90060301_108_dialog_content = "Hmm... Preciso dar uma olhada nisso!",
  str_homestory_N26dianying_90060301_108X1_dialog_content = "Tudo bem, você venceu... Aqui está. Dirija-se para a direção que estou enfrentando.",
  str_homestory_N26dianying_90060301_108X2_dialog_content = "Tudo bem, você venceu... Aqui está. Dirija-se para a direção que estou enfrentando.",
  str_homestory_N26dianying_90060301_108X3_dialog_content = "Para onde eu vou?",
  str_homestory_N26dianying_90060301_108X4_dialog_content = "Não se preocupe com isso. Apenas siga em frente!",
  str_homestory_N26dianying_90060301_108X5_dialog_content = "Sempre há uma nova esperança à sua frente na Aldeia dos Dragões, uma terra de pessoas incríveis!",
  str_homestory_N26dianying_90060301_108X6_dialog_content = "Não se preocupe com isso. Apenas siga em frente!",
  str_homestory_N26dianying_90060301_108X7_dialog_content = "Sempre há uma nova esperança à sua frente na Aldeia dos Dragões, uma terra de pessoas incríveis!",
  str_homestory_N26dianying_90060301_108X8_dialog_content = "R-Sério!? Isso não é muito casual...",
  str_homestory_N26dianying_90060301_108X9_dialog_content = "Nossa, eu estava certo. Faz tanto tempo que estou andando... O patrão deve ser um trapaceiro!",
  str_homestory_N26dianying_90060301_108X10_dialog_content = "Huh? Este poderia ser...",
  str_homestory_N26dianying_90060301_109_dialog_content = "\"O caminho do mundo é buscar o ganho pessoal e, por isso, o mundo nunca mudará. Para evitar que a Lâmina Celestial caia nas mãos dos ímpios...\"",
  str_homestory_N26dianying_90060301_110_dialog_content = "\"Um poço antigo na Vila dos Dragões foi abençoado com o poder de revelar a espada lendária.\"",
  str_homestory_N26dianying_90060301_111_dialog_content = "\"Imbuído de Luminatics misteriosos, este poço não mostrará o reflexo de nenhum objeto levantado em suas águas.\"",
  str_homestory_N26dianying_90060301_112_dialog_content = "\"Quando a verdadeira Lâmina Celestial se aproximar, sua imagem divina aparecerá dentro do poço...\"",
  str_homestory_N26dianying_90060301_113_dialog_content = "\"O caminho do mundo é buscar o ganho pessoal e, por isso, o mundo nunca mudará. Para evitar que a Lâmina Celestial caia nas mãos dos ímpios...\"",
  str_homestory_N26dianying_90060301_114_dialog_content = "\"Uma espreguiçadeira na Vila dos Dragões foi abençoada com o poder de revelar a lendária espada.\"",
  str_homestory_N26dianying_90060301_115_dialog_content = "\"Imbuída de Luminatics misteriosos, esta cadeira não permitirá que ninguém descanse em seu assento.\"",
  str_homestory_N26dianying_90060301_116_dialog_content = "\"Quando a verdadeira Lâmina Celestial se aproximar, sua imagem divina aparecerá no assento...\"",
  str_homestory_N26dianying_90060301_117_dialog_content = "\"O caminho do mundo é buscar o ganho pessoal e, por isso, o mundo nunca mudará. Para evitar que a Lâmina Celestial caia nas mãos dos ímpios...\"",
  str_homestory_N26dianying_90060301_118_dialog_content = "\"Um piano na Vila dos Dragões foi abençoado com o poder de revelar a lendária espada.\"",
  str_homestory_N26dianying_90060301_119_dialog_content = "\"Imbuído de misteriosos Luminatics, este piano não permitirá que ninguém o toque.\"",
  str_homestory_N26dianying_90060301_120_dialog_content = "\"Quando a verdadeira Lâmina Celestial se aproximar, sua imagem divina aparecerá nas teclas do piano...\"",
  str_homestory_N26dianying_90060301_121_dialog_content = "... Yao? É você, Yao?",
  str_homestory_N26dianying_90060301_122_dialog_content = "Yao? É realmente você?",
  str_homestory_N26dianying_90060301_123_dialog_content = "Sou eu, a vizinha de quando éramos crianças! Não te vejo há séculos, Yao!",
  str_homestory_N26dianying_90060301_124_dialog_content = "Não desde o dia em que você deixou a vila para encontrar trabalho... Achei que nunca mais te veria!",
  str_homestory_N26dianying_90060301_125_dialog_content = "De qualquer forma, você está procurando algo, por acaso?",
  str_homestory_N26dianying_90060301_126_dialog_content = "Depois que nós dois saímos da vila para encontrar trabalho... Achei que nunca mais veria você!",
  str_homestory_N26dianying_90060301_127_dialog_content = "De qualquer forma, você está procurando algo, por acaso?",
  str_homestory_N26dianying_90060301_128_dialog_content = "É uma longa história, mas... Você ainda se lembra onde encontrar esse poço? Você conhece aquele, certo?",
  str_homestory_N26dianying_90060301_129_dialog_content = "É uma longa história, mas... Você ainda se lembra onde encontrar aquela espreguiçadeira? Você conhece aquele, certo?",
  str_homestory_N26dianying_90060301_130_dialog_content = "É uma longa história, mas... Você ainda se lembra onde encontrar aquele piano? Você conhece aquele, certo?",
  str_homestory_N26dianying_90060301_131_dialog_content = "Claro, apenas siga-me e eu vou te mostrar.",
  str_homestory_N26dianying_90060301_132_dialog_content = "Aqui estamos!",
  str_homestory_N26dianying_90060301_133_dialog_content = "Claro, apenas siga-me e eu vou te mostrar.",
  str_homestory_N26dianying_90060301_134_dialog_content = "Tudo bem, aqui estamos nós!",
  str_homestory_N26dianying_90060301_135_dialog_content = "Então... Você realmente veio para casa só para ver isso bem?",
  str_homestory_N26dianying_90060301_136_dialog_content = "Então... Você realmente voltou para casa só para ver esta cadeira?",
  str_homestory_N26dianying_90060301_137_dialog_content = "Então... Você realmente voltou para casa só para ver este piano?",
  str_homestory_N26dianying_90060301_138_dialog_content = "Bem, a verdade é que... vim em busca de pistas sobre o paradeiro da Lâmina Celestial.",
  str_homestory_N26dianying_90060301_139_dialog_content = "Meus senhores me ordenaram que o encontrasse e o trouxesse de volta para eles o mais rápido possível.",
  str_homestory_N26dianying_90060301_140_dialog_content = "<color=#FFB400>\"Senhores\"</color>? Como em \"mais de um\"?",
  str_homestory_N26dianying_90060301_141_dialog_content = "<color=#FFB400>\"Senhores\"</color>? Como em \"mais de um\"? ...Oh, você quer dizer seus chefes!",
  str_homestory_N26dianying_90060301_142_dialog_content = "Isso mesmo... Ambos me confiaram a mesma missão, ao mesmo tempo, então estou aqui.",
  str_homestory_N26dianying_90060301_143_dialog_content = "Embora eu não tenha certeza do que farei quando o encontrar... Como devo decidir a quem entregá-lo?",
  str_homestory_N26dianying_90060301_144_dialog_content = "Por que não ter seus \"senhores\" <color=#FFB400>lutar entre si</color> para isso?",
  str_homestory_N26dianying_90060301_145_dialog_content = "De qualquer forma, a água deste poço é totalmente turva. Não vejo uma \"imagem divina\" em nenhum lugar aqui...",
  str_homestory_N26dianying_90060301_146_dialog_content = "De qualquer forma, esta cadeira está totalmente vazia. Não vejo uma \"imagem divina\" em lugar algum...",
  str_homestory_N26dianying_90060301_147_dialog_content = "De qualquer forma, as teclas deste piano são impecáveis. Não vejo uma \"imagem divina\" em nenhum lugar deles...",
  str_homestory_N26dianying_90060301_147X1_dialog_content = "... Yao? É você, Yao?",
  str_homestory_N26dianying_90060301_147X2_dialog_content = "Yao? É realmente você?",
  str_homestory_N26dianying_90060301_147X3_dialog_content = "Sou eu, a vizinha de quando éramos crianças! Não te vejo há séculos, Yao!",
  str_homestory_N26dianying_90060301_147X4_dialog_content = "Não desde o dia em que você deixou a vila para encontrar trabalho... Achei que nunca mais te veria!",
  str_homestory_N26dianying_90060301_147X5_dialog_content = "De qualquer forma, você está procurando algo, por acaso?",
  str_homestory_N26dianying_90060301_147X6_dialog_content = "Depois que nós dois saímos da vila para encontrar trabalho... Achei que nunca mais veria você!",
  str_homestory_N26dianying_90060301_147X7_dialog_content = "A propósito, o que você está fazendo?",
  str_homestory_N26dianying_90060301_147X8_dialog_content = "Hum, não mencione isso. Meus dois senhores me pediram para procurar a mesma Lâmina Celestial.",
  str_homestory_N26dianying_90060301_147X9_dialog_content = "Enfim, não consegui encontrar nada...",
  str_homestory_N26dianying_90060301_147X10_dialog_content = "Então você tem servido a dois mestres o tempo todo! E depois que eu confiei em você tão de perto!",
  str_homestory_N26dianying_90060301_147X11_dialog_content = "L-Lorde Zakura?! O-O que você está fazendo aqui...?",
  str_homestory_N26dianying_90060301_147X12_dialog_content = "Eu deveria estar te fazendo a mesma pergunta! Palavras não podem expressar como estou decepcionado com você, meu chamado \"servo fiel\"!",
  str_homestory_N26dianying_90060301_147X13_dialog_content = "L-Lord Dragonscorch?! Você também está aqui?!",
  str_homestory_N26dianying_90060301_147X14_dialog_content = "Uh... O-O que está acontecendo aqui?",
  str_homestory_N26dianying_90060301_147X15_dialog_content = "Uh... O-O que está acontecendo aqui?",
  str_homestory_N26dianying_90060301_147X16_dialog_content = "Uh-oh... Parece que o gabarito acabou! Chubb!",
  str_homestory_N26dianying_90060301_147X17_dialog_content = "Eu estava preocupado que esta tarefa fosse muito grande para você sozinho, então providenciei para que alguém o seguisse durante sua missão...",
  str_homestory_N26dianying_90060301_147X18_dialog_content = "E relate tudo para mim quando acontecer. Era para servir como um teste de suas habilidades.",
  str_homestory_N26dianying_90060301_147X19_dialog_content = "Quando soube que sua busca havia começado a dar frutos, corri para ajudá-lo a encontrar a Lâmina Celestial...",
  str_homestory_N26dianying_90060301_147X20_dialog_content = "Apenas para ouvir você proferir aquelas terríveis, terríveis palavras!",
  str_homestory_N26dianying_90060301_147X21_dialog_content = "Nós iremos? O que você tem a dizer em sua defesa, traidor?!",
  str_homestory_N26dianying_90060301_147X22_dialog_content = "Bom... já que as coisas chegaram a esse ponto, eu me responsabilizo por isso!",
  str_homestory_N26dianying_90060301_147X23_dialog_content = "Tomem medidas, meus senhores! Eu conheço as regras. Hoje é o dia que eu morro!",
  str_homestory_N26dianying_90060301_147X24_dialog_content = "Hã?",
  str_homestory_N26dianying_90060301_147X25_dialog_content = "Matar você? Que tipo de piada é essa?",
  str_homestory_N26dianying_90060301_147X26_dialog_content = "Como um guerreiro orgulhoso, eu nunca mataria um oponente desarmado.",
  str_homestory_N26dianying_90060301_147X27_dialog_content = "Apesar de sua traição, seu remorso parece genuíno... Muito bem, meu servo. Vamos para casa, para que você possa ser punido de acordo.",
  str_homestory_N26dianying_90060301_147X28_dialog_content = "Que? Eu fui o primeiro a chegar, então a punição do Dragonscorch deveria vir primeiro!",
  str_homestory_N26dianying_90060301_147X29_dialog_content = "Eu digo Zakura!",
  str_homestory_N26dianying_90060301_147X30_dialog_content = "Eu digo Dragonscorch!",
  str_homestory_N26dianying_90060301_147X31_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_147X32_dialog_content = "Por favor, meus senhores... Isso não é algo pelo qual vocês deveriam estar brigando...",
  str_homestory_N26dianying_90060301_148_dialog_content = "Então você tem servido a dois mestres o tempo todo! E depois que eu confiei em você tão de perto!",
  str_homestory_N26dianying_90060301_149_dialog_content = "L-Lorde Zakura?! O-O que você está fazendo aqui...?",
  str_homestory_N26dianying_90060301_150_dialog_content = "Eu deveria estar te fazendo a mesma pergunta! Palavras não podem expressar o quanto estou decepcionado com você, meu chamado \"servo fiel\"!",
  str_homestory_N26dianying_90060301_151_dialog_content = "L-Lord Dragonscorch?! Você também está aqui?!",
  str_homestory_N26dianying_90060301_152_dialog_content = "Uh... O-O que está acontecendo aqui?",
  str_homestory_N26dianying_90060301_153_dialog_content = "Uh... O-O que está acontecendo aqui?",
  str_homestory_N26dianying_90060301_154_dialog_content = "Uh-oh... Parece que o gabarito acabou! Chubb!",
  str_homestory_N26dianying_90060301_155_dialog_content = "Eu estava preocupado que esta tarefa fosse muito grande para você sozinho, então providenciei para que alguém o seguisse durante sua missão...",
  str_homestory_N26dianying_90060301_156_dialog_content = "E relate tudo para mim quando acontecer. Era para servir como um teste de suas habilidades.",
  str_homestory_N26dianying_90060301_157_dialog_content = "Quando soube que sua busca havia começado a dar frutos, corri para ajudá-lo a encontrar a Lâmina Celestial...",
  str_homestory_N26dianying_90060301_158_dialog_content = "Apenas para ouvir você proferir aquelas terríveis, terríveis palavras!",
  str_homestory_N26dianying_90060301_159_dialog_content = "Nós iremos? O que você tem a dizer em sua defesa, traidor?!",
  str_homestory_N26dianying_90060301_160_dialog_content = "Eh?!",
  str_homestory_N26dianying_90060301_161_dialog_content = "Você ousa zombar de mim?!",
  str_homestory_N26dianying_90060301_162_dialog_content = "(Eles pensam exatamente igual, não é...)",
  str_homestory_N26dianying_90060301_163_dialog_content = "Eles estão em perfeita harmonia! Chubb!",
  str_homestory_N26dianying_90060301_164_dialog_content = "Lorde Dragonscorch... Deve ser o destino. Que melhor momento para decidir, de uma vez por todas, quem é o mais forte... do que agora mesmo!",
  str_homestory_N26dianying_90060301_165_dialog_content = "Você tirou as palavras da minha boca. Hoje é o dia em que o Dragonscorch prova sua supremacia!",
  str_homestory_N26dianying_90060301_166_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_167_dialog_content = "(Oh merda... Eles estão prestes a se separar! Eu tenho que fazer algo sobre isso...)",
  str_homestory_N26dianying_90060301_168_option_content = "Encontre a Lâmina Celestial!",
  str_homestory_N26dianying_90060301_169_dialog_content = "Ei! Não se esqueça do objetivo de sua busca!",
  str_homestory_N26dianying_90060301_170_dialog_content = "Isso mesmo! O que mais importa agora... É encontrar a Lâmina Celestial!",
  str_homestory_N26dianying_90060301_171_dialog_content = "Talvez se eu olhar mais de perto, sua \"imagem divina\" apareça...",
  str_homestory_N26dianying_90060301_172_dialog_content = "A-ahn?!",
  str_homestory_N26dianying_90060301_173_dialog_content = "Meus senhores! Venha ver, rapidamente!",
  str_homestory_N26dianying_90060301_174_dialog_content = "Hum?",
  str_homestory_N26dianying_90060301_175_dialog_content = "Poderia ser... A Lâmina Celestial?!",
  str_homestory_N26dianying_90060301_176_dialog_content = "O que é isto...?",
  str_homestory_N26dianying_90060301_177_dialog_content = "Por que minha lâmina está brilhando assim?",
  str_homestory_N26dianying_90060301_178_dialog_content = "Bem, já estava na hora! Finalmente, a Lâmina Celestial foi unida mais uma vez!",
  str_homestory_N26dianying_90060301_179_dialog_content = "Bem, já estava na hora! Finalmente, a Lâmina Celestial foi unida mais uma vez!",
  str_homestory_N26dianying_90060301_180_dialog_content = "Quer dizer que...",
  str_homestory_N26dianying_90060301_181_dialog_content = "Isso mesmo! A chamada \"Lâmina Celestial\"... É na verdade um par de espadas! E somente quando eles estiverem juntos, seu verdadeiro poder finalmente se revelará.",
  str_homestory_N26dianying_90060301_182_dialog_content = "Há muito tempo, tive o privilégio de assistir a dois grandes guerreiros cortarem dezenas de Eclipsites com essas duas lâminas...",
  str_homestory_N26dianying_90060301_183_dialog_content = "Isso mesmo! Na verdade, existem DUAS Lâminas Celestiais, e seu verdadeiro poder só se revelará quando elas forem reunidas!",
  str_homestory_N26dianying_90060301_184_dialog_content = "Quando eu ainda era pequeno, vi dois guerreiros lendários cortarem um exército de eclipsitas com essas duas lâminas...",
  str_homestory_N26dianying_90060301_185_dialog_content = "Essa foi a última vez que as duas espadas foram usadas juntas. Depois dessa batalha, eles caíram em mãos separadas e foram mantidos longe um do outro desde então.",
  str_homestory_N26dianying_90060301_186_dialog_content = "Essa foi a última vez que as duas espadas foram usadas juntas. Depois dessa batalha, eles caíram em mãos separadas e foram mantidos longe um do outro desde então.",
  str_homestory_N26dianying_90060301_187_dialog_content = "Mas agora, a Lâmina Celestial está inteira mais uma vez!",
  str_homestory_N26dianying_90060301_188_dialog_content = "Mas agora, a Lâmina Celestial está inteira mais uma vez!",
  str_homestory_N26dianying_90060301_189_dialog_content = "Th-Isso mesmo, meus senhores! Apesar de suas diferenças, seus objetivos são um e o mesmo... Vocês até pensam muito parecidos!",
  str_homestory_N26dianying_90060301_190_dialog_content = "Em vez de lutar entre si, por que não unir suas forças e salvar o mundo juntos?",
  str_homestory_N26dianying_90060301_191_dialog_content = "Hum...",
  str_homestory_N26dianying_90060301_192_dialog_content = "É...",
  str_homestory_N26dianying_90060301_193_dialog_content = "O servo faz uma observação válida... Afinal, nós dois buscamos o poder da Lâmina Celestial.",
  str_homestory_N26dianying_90060301_194_dialog_content = "E se unirmos nossas forças, ainda seremos os líderes da facção mais poderosa do mundo.",
  str_homestory_N26dianying_90060301_195_dialog_content = "Quanto a você, nosso servo \"fiel\"...",
  str_homestory_N26dianying_90060301_196_dialog_content = "Uh-oh...",
  str_homestory_N26dianying_90060301_197_dialog_content = "Você provou seu valor, e o Zakura estará para sempre em dívida com você!",
  str_homestory_N26dianying_90060301_198_dialog_content = "O Dragonscorch deve muito aos seus esforços diligentes também!",
  str_homestory_N26dianying_90060301_199_dialog_content = "<size=45>Meus senhores!</size>",
  str_homestory_N26dianying_90060301_200_dialog_content = "Heheheh... E assim nasceu uma nova lenda!",
  str_homestory_N26dianying_90060301_201_dialog_content = "Heehee! E assim nasceu uma nova lenda!",
  str_homestory_N26dianying_90060301_202_dialog_content = "\"No final, Zakura e Dragonscorch deixaram de lado suas diferenças e se fundiram em um poderoso exército.\"",
  str_homestory_N26dianying_90060301_203_dialog_content = "\"Com sua força combinada, assim como o poder da Lâmina Celestial, o mundo foi abençoado com a paz mais uma vez.\"",
  str_homestory_N26dianying_90060301_204_dialog_content = "\"No final, Zakura e Dragonscorch deixaram de lado suas diferenças e se fundiram em um poderoso exército.\"",
  str_homestory_N26dianying_90060301_205_dialog_content = "\"Com sua força combinada, assim como o poder da Lâmina Celestial, o mundo foi abençoado com a paz mais uma vez.\"",
  str_homestory_N26dianying_90060301_206_option_content = "Tente fazer as pazes!",
  str_homestory_N26dianying_90060301_207_dialog_content = "Você conhece esses dois melhor do que ninguém! Vá resolver as coisas entre eles!",
  str_homestory_N26dianying_90060301_208_dialog_content = "Isso mesmo! Como servo deles, sou o único que pode resolver suas diferenças!",
  str_homestory_N26dianying_90060301_209_dialog_content = "Meus senhores, se posso falar? Apesar de suas diferenças, seus objetivos são os mesmos... Vocês até pensam muito parecidos!",
  str_homestory_N26dianying_90060301_210_dialog_content = "Em vez de lutar entre si, por que não unir suas forças e salvar o mundo juntos?",
  str_homestory_N26dianying_90060301_211_dialog_content = "Hum...",
  str_homestory_N26dianying_90060301_212_dialog_content = "É...",
  str_homestory_N26dianying_90060301_213_dialog_content = "O servo faz um ponto válido. Como líderes de nossas respectivas facções, é nosso dever proteger o mundo da ameaça Eclipsite.",
  str_homestory_N26dianying_90060301_214_dialog_content = "E se unirmos nossas forças, ainda seremos os líderes da facção mais poderosa do mundo.",
  str_homestory_N26dianying_90060301_215_dialog_content = "Quanto a você, nosso servo \"fiel\"...",
  str_homestory_N26dianying_90060301_216_dialog_content = "Uh-oh...",
  str_homestory_N26dianying_90060301_217_dialog_content = "Embora você tenha falhado em sua busca para encontrar a Lâmina Celestial... Pode haver outra maneira de salvar o mundo.",
  str_homestory_N26dianying_90060301_218_dialog_content = "Se o Dragonscorch e Zakura se tornarem um, não haveria necessidade de puni-lo por sua traição.",
  str_homestory_N26dianying_90060301_219_dialog_content = "<size=45>Meus senhores!</size>",
  str_homestory_N26dianying_90060301_220_dialog_content = "Heheheh... E assim nasceu uma nova lenda!",
  str_homestory_N26dianying_90060301_221_dialog_content = "Heehee! E assim nasceu uma nova lenda!",
  str_homestory_N26dianying_90060301_222_dialog_content = "\"No final, Zakura e Dragonscorch deixaram de lado suas diferenças e se fundiram em um poderoso exército.\"",
  str_homestory_N26dianying_90060301_223_dialog_content = "\"E assim, o mundo foi abençoado com a paz mais uma vez.\"",
  str_homestory_N26dianying_90060301_224_dialog_content = "\"No final, Zakura e Dragonscorch deixaram de lado suas diferenças e se fundiram em um poderoso exército.\"",
  str_homestory_N26dianying_90060301_225_dialog_content = "\"E assim, o mundo foi abençoado com a paz mais uma vez.\"",
  str_homestory_N26dianying_90060301_226_option_content = "Apenas me mate!",
  str_homestory_N26dianying_90060301_227_dialog_content = "O-O que devo fazer? Não vejo mais como consertar as coisas...",
  str_homestory_N26dianying_90060301_228_dialog_content = "Não, espere... É minha culpa que as coisas tenham acontecido desse jeito. Eu tenho que assumir a responsabilidade por minhas ações...",
  str_homestory_N26dianying_90060301_229_dialog_content = "Meus senhores! Eu sou o único culpado por tudo isso! Se você vai matar alguém, me mate!",
  str_homestory_N26dianying_90060301_230_dialog_content = "Hã?",
  str_homestory_N26dianying_90060301_231_dialog_content = "Matar você? Que tipo de piada é essa?",
  str_homestory_N26dianying_90060301_232_dialog_content = "Como um guerreiro orgulhoso, eu nunca mataria um oponente desarmado.",
  str_homestory_N26dianying_90060301_233_dialog_content = "Apesar de sua traição, seu remorso parece genuíno... Muito bem, meu servo. Vamos para casa, para que você possa ser punido de acordo.",
  str_homestory_N26dianying_90060301_234_dialog_content = "Que? Eu fui o primeiro a chegar, então a punição do Dragonscorch deveria vir primeiro!",
  str_homestory_N26dianying_90060301_235_dialog_content = "Eu digo Zakura!",
  str_homestory_N26dianying_90060301_236_dialog_content = "Eu digo Dragonscorch!",
  str_homestory_N26dianying_90060301_237_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_238_dialog_content = "Por favor, meus senhores... Isso não é algo pelo qual vocês deveriam estar brigando...",
  str_homestory_N26dianying_90060301_239_dialog_content = "Se bem me lembro, esta loja vende algumas das melhores armas de toda a Vila dos Dragões!",
  str_homestory_N26dianying_90060301_240_dialog_content = "Hã?!",
  str_homestory_N26dianying_90060301_241_dialog_content = "O que aconteceu com todas as armas? A loja está completamente vazia!",
  str_homestory_N26dianying_90060301_242_dialog_content = "Não me lembre... Desculpe amigo, mas estou fechando de vez.",
  str_homestory_N26dianying_90060301_243_dialog_content = "*Soluçando* Não me lembre... Desculpe, mas a loja acabou.",
  str_homestory_N26dianying_90060301_244_dialog_content = "O que houve?",
  str_homestory_N26dianying_90060301_245_dialog_content = "A vila foi saqueada por uma gangue de bandidos ontem.",
  str_homestory_N26dianying_90060301_246_dialog_content = "A vila foi saqueada por uma gangue de bandidos ontem.",
  str_homestory_N26dianying_90060301_247_dialog_content = "Eles levaram tudo! Minhas armas, meu dinheiro, a escritura da minha casa... Levaram até meu porta-armas favorito!",
  str_homestory_N26dianying_90060301_248_dialog_content = "Eles levaram tudo! Minhas conchas de água benta, meu dinheiro... Levaram até meu porta-armas mecânico favorito!",
  str_homestory_N26dianying_90060301_249_dialog_content = "Eu não tenho mais nada!",
  str_homestory_N26dianying_90060301_250_dialog_content = "Eu não tenho mais nada!",
  str_homestory_N26dianying_90060301_251_dialog_content = "N-Nada mesmo?!",
  str_homestory_N26dianying_90060301_252_dialog_content = "Me desculpe, eu sei que provavelmente não é o momento certo para perguntar... Mas você já ouviu falar da lendária Lâmina Celestial?",
  str_homestory_N26dianying_90060301_253_dialog_content = "Huh? Oh, deixe-me em paz já...",
  str_homestory_N26dianying_90060301_254_dialog_content = "Huh? Oh, deixe-me em paz já...",
  str_homestory_N26dianying_90060301_255_dialog_content = "Você não pode ver que estou chafurdando em desespero agora?!",
  str_homestory_N26dianying_90060301_256_dialog_content = "Não posso me forçar a sorrir agora, muito menos falar sobre armas...",
  str_homestory_N26dianying_90060301_257_dialog_content = "Mas...",
  str_homestory_N26dianying_90060301_258_dialog_content = "Pronto, chega! A loja está fechada, e é isso!",
  str_homestory_N26dianying_90060301_259_dialog_content = "Pronto, chega! A loja está fechada, e é isso!",
  str_homestory_N26dianying_90060301_260_dialog_content = "Agora veja-se fora e nunca mais volte!",
  str_homestory_N26dianying_90060301_261_dialog_content = "Agora, se você me der licença, eu tenho que ir fazer algumas novas Conchas de Água Benta...",
  str_homestory_N26dianying_90060301_262_dialog_content = "N-Não, por favor! Não vá...!",
